import { sql } from "drizzle-orm";
import { pgTable, text, varchar, integer, jsonb, timestamp } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
});

export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;

export const promptTemplates = pgTable("prompt_templates", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: text("name").notNull().unique(),
  content: text("content").notNull(),
  systemContent: text("system_content"),
  inheritGlobalPrompt: integer("inherit_global_prompt").notNull().default(1),
  description: text("description"),
  version: integer("version").notNull().default(1),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertPromptTemplateSchema = createInsertSchema(promptTemplates).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertPromptTemplate = z.infer<typeof insertPromptTemplateSchema>;
export type PromptTemplate = typeof promptTemplates.$inferSelect;

export const llmLogs = pgTable("llm_logs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  promptTemplateId: varchar("prompt_template_id"),
  gameId: varchar("game_id"),
  turnNumber: integer("turn_number"),
  functionName: text("function_name").notNull(),
  prompt: text("prompt").notNull(),
  response: text("response").notNull(),
  metadata: jsonb("metadata"),
  executionTimeMs: integer("execution_time_ms"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

export const insertLlmLogSchema = createInsertSchema(llmLogs).omit({
  id: true,
  createdAt: true,
});

export type InsertLlmLog = z.infer<typeof insertLlmLogSchema>;
export type LlmLog = typeof llmLogs.$inferSelect;

export const events = pgTable("events", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: text("name").notNull(),
  segment: text("segment").notNull(),
  skill: text("skill").notNull(),
  dc: integer("dc").notNull(),
  triggerCondition: jsonb("trigger_condition").notNull(),
  passEffect: text("pass_effect").notNull(),
  failEffect: text("fail_effect").notNull(),
  tags: jsonb("tags").notNull(),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertEventSchema = createInsertSchema(events).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertEvent = z.infer<typeof insertEventSchema>;
export type Event = typeof events.$inferSelect;

export const items = pgTable("items", {
  id: varchar("id").primaryKey(),
  name: text("name").notNull(),
  description: text("description").notNull(),
  icon: text("icon").notNull(),
  skillBonusSkill: text("skill_bonus_skill"),
  skillBonusValue: integer("skill_bonus_value"),
  sceneEffectTags: jsonb("scene_effect_tags"),
  sceneEffectEffect: text("scene_effect_effect"),
  efficiency: jsonb("efficiency"),
  tags: jsonb("tags").notNull(),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertItemSchema = createInsertSchema(items).omit({
  createdAt: true,
  updatedAt: true,
});

export type InsertItem = z.infer<typeof insertItemSchema>;
export type ItemRow = typeof items.$inferSelect;

export const npcTemplates = pgTable("npc_templates", {
  id: varchar("id").primaryKey(),
  name: text("name").notNull(),
  role: text("role").notNull(),
  bio: text("bio"),
  startingAffinity: integer("starting_affinity").notNull().default(0),
  tags: jsonb("tags").notNull(),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertNpcTemplateSchema = createInsertSchema(npcTemplates).omit({
  createdAt: true,
  updatedAt: true,
});

export type InsertNpcTemplate = z.infer<typeof insertNpcTemplateSchema>;
export type NpcTemplate = typeof npcTemplates.$inferSelect;

export const imagePrompts = pgTable("image_prompts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: text("name").notNull(),
  promptTemplate: text("prompt_template").notNull(),
  inheritVisualStyle: integer("inherit_visual_style").notNull().default(1),
  size: text("size").notNull().default("1024x1024"),
  quality: text("quality").notNull().default("auto"),
  description: text("description"),
  sceneTypes: jsonb("scene_types").notNull(),
  tags: jsonb("tags").notNull(),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertImagePromptSchema = createInsertSchema(imagePrompts).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertImagePrompt = z.infer<typeof insertImagePromptSchema>;
export type ImagePrompt = typeof imagePrompts.$inferSelect;

export const interviewQuestions = pgTable("interview_questions", {
  id: varchar("id").primaryKey(),
  question: text("question").notNull(),
  variableName: text("variable_name").notNull(),
  description: text("description"),
  displayOrder: integer("display_order").notNull().default(0),
  tags: jsonb("tags").notNull(),
  active: integer("active").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertInterviewQuestionSchema = createInsertSchema(interviewQuestions).omit({
  createdAt: true,
  updatedAt: true,
});

export type InsertInterviewQuestion = z.infer<typeof insertInterviewQuestionSchema>;
export type InterviewQuestion = typeof interviewQuestions.$inferSelect;

export const generatedImages = pgTable("generated_images", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  templateName: text("template_name").notNull(),
  promptHash: varchar("prompt_hash").notNull(),
  variablesHash: varchar("variables_hash").notNull(),
  filePath: text("file_path").notNull(),
  fileSize: integer("file_size").notNull(),
  mimeType: text("mime_type").notNull().default("image/png"),
  sceneFingerprint: jsonb("scene_fingerprint").notNull(),
  metadata: jsonb("metadata").notNull(),
  gameId: varchar("game_id"),
  turnNumber: integer("turn_number"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  accessedAt: timestamp("accessed_at").notNull().defaultNow(),
  accessCount: integer("access_count").notNull().default(1),
});

export const insertGeneratedImageSchema = createInsertSchema(generatedImages).omit({
  id: true,
  createdAt: true,
  accessedAt: true,
});

export type InsertGeneratedImage = z.infer<typeof insertGeneratedImageSchema>;
export type GeneratedImage = typeof generatedImages.$inferSelect;

export const games = pgTable("games", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  username: text("username").notNull(),
  seed: text("seed").notNull(),
  day: integer("day").notNull().default(1),
  turnNumber: integer("turn_number").notNull().default(0),
  segment: text("segment").notNull().default('Departure'),
  absurdity: integer("absurdity").notNull().default(2),
  displayMode: varchar("display_mode").notNull().default('modern'),
  stats: jsonb("stats").notNull(),
  npcs: jsonb("npcs").notNull(),
  equippedItems: jsonb("equipped_items").notNull(),
  turns: jsonb("turns").notNull(),
  currentActions: jsonb("current_actions").notNull(),
  runningGags: jsonb("running_gags").notNull(),
  eventHistory: jsonb("event_history").notNull(),
  interviewResponses: jsonb("interview_responses").notNull().default(sql`'{}'::jsonb`),
  isComplete: integer("is_complete").notNull().default(0),
  failureReason: text("failure_reason"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertGameSchema = createInsertSchema(games).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertGame = z.infer<typeof insertGameSchema>;
export type SelectGame = typeof games.$inferSelect;

// Game state types
export type Skill = 'Bureaucracy' | 'Engineering' | 'Piloting' | 'Culinary' | 'Diplomacy' | 'Deception' | 'Vibes';
export type Intent = 'repair' | 'negotiate' | 'cook' | 'explore' | 'improvise' | 'research' | 'command' | 'other';
export type Risk = 'Safe' | 'Risky' | 'Wild';
export type Segment = 'Departure' | 'Belt' | 'Outer Darkness' | 'Approach';
export type NPCStatus = 'Rivalry' | 'Crush' | 'Indifferent';

// NPC Skill Mappings - defines which skills each crew member specializes in
export const NPC_SKILL_MAPPINGS: Record<string, Skill[]> = {
  'Pilot Lyra': ['Piloting', 'Deception'],
  'Engineer Grom': ['Engineering', 'Bureaucracy'],
  'Doctor Moss': ['Bureaucracy', 'Culinary'],
  'Coffee-9000': ['Diplomacy', 'Vibes']
} as const;

export interface GameStats {
  hull: number;
  oxygen: number;
  fuel: number;
  food: number;
  morale: number;
  weirdness: number;
}

export interface NPC {
  id: string;
  name: string;
  role: string;
  affinity: number;
  status: NPCStatus;
  lastInteraction?: string;
}

export interface Item {
  id: string;
  name: string;
  description: string;
  icon: string;
  skillBonus?: { skill: Skill; bonus: number };
  sceneEffect?: { tags: string[]; effect: string };
  efficiency?: {
    oxygen?: number;
    fuel?: number;
    food?: number;
    morale?: number;
  };
}

export interface Check {
  skill: Skill;
  dc: number;
  roll: number;
  success: boolean;
  description?: string;
}

export interface DeltaChange {
  stat: string;
  change: number;
  note?: string;
}

export interface Turn {
  turnNumber: number;
  narrative: string;
  checks: Check[];
  delta: DeltaChange[];
  timestamp: number;
  imageUrl?: string;
  imageTemplate?: string;
}

export interface ActionChip {
  action: string;
  summary: string;
  risk: Risk;
  intent: Intent;
  usesItemId?: string;
}

export interface GameState {
  id: string;
  username: string;
  seed: string;
  day: number;
  turnNumber: number;
  segment: Segment;
  absurdity: number;
  displayMode?: 'modern' | 'terminal';
  stats: GameStats;
  npcs: NPC[];
  equippedItems: string[];
  turns: Turn[];
  currentActions: ActionChip[];
  runningGags: string[];
  eventHistory: string[];
  interviewResponses: Record<string, string>;
  isComplete: boolean;
  failureReason?: string;
}

// Insert schemas
export const insertGameStateSchema = z.object({
  username: z.string().min(1, "Captain name required"),
  seed: z.string().optional(),
  absurdity: z.number().min(0).max(3).default(2),
  displayMode: z.enum(['modern', 'terminal']).default('modern'),
});

export type InsertGameState = z.infer<typeof insertGameStateSchema>;

export const actionInputSchema = z.object({
  gameId: z.string(),
  action: z.string(),
  customText: z.string().optional(),
});

export type ActionInput = z.infer<typeof actionInputSchema>;

// Event trigger condition types
export type TriggerCondition = 
  | { type: 'stat'; stat: keyof GameStats; operator: '>=' | '<=' | '>' | '<' | '=='; value: number }
  | { type: 'day_modulo'; divisor: number; remainder: number }
  | { type: 'random'; chance: number }
  | { type: 'or'; conditions: TriggerCondition[] }
  | { type: 'and'; conditions: TriggerCondition[] };

// Event definition (runtime version with evaluated trigger)
export interface EventDefinition {
  id: string;
  name: string;
  segment: Segment | 'Any';
  tags: string[];
  triggerCondition: TriggerCondition;
  skill: Skill;
  dc: number;
  passEffect: string;
  failEffect: string;
  active: boolean;
}

// Items are now loaded from database via itemCache
// Use getActiveItems() to get all items
// Use getItemById(id) to get a specific item

