server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { randomUUID } from "crypto";
import type { GameState, ActionInput, InsertGameState, Intent } from "@shared/schema";
import { insertGameStateSchema, actionInputSchema, NPC_SKILL_MAPPINGS } from "@shared/schema";
import { 
  SeededRandom, 
  getSegment, 
  calculateDC, 
  clampStat, 
  checkFailState, 
  checkWinCondition,
  getTriggeredEvents,
  applyDelta,
  calculateDailyConsumption
} from "./gameEngine";
import { getInitialNpcs } from "./npcCache";
import { getActiveItems, getItemById } from "./itemCache";
import { generateNarrative, generateActions, mapCustomActionToIntent, generateIntroduction, generateImage, testGenerateImage, generateInterviewAnswer } from "./aiService";
import { syncPromptsFromDatabase, getCacheStats } from "./promptCache";
import { loadEventsIntoMemory, getCacheStats as getEventCacheStats } from "./eventCache";
import { loadItemsIntoMemory, getCacheStats as getItemCacheStats } from "./itemCache";
import { loadNpcTemplatesIntoMemory, getCacheStats as getNpcCacheStats } from "./npcCache";
import { loadImagePromptsIntoMemory, getImagePromptCacheStats } from "./imagePromptCache";

export async function registerRoutes(app: Express): Promise<Server> {

  // Start a new game
  app.post("/api/game/start", async (req, res) => {
    try {
      const validated = insertGameStateSchema.parse(req.body);

      const gameId = randomUUID();
      const initialState: GameState = {
        id: gameId,
        username: validated.username,
        seed: validated.seed || randomUUID(),
        day: 1,
        turnNumber: 0,
        segment: 'Departure',
        absurdity: validated.absurdity,
        displayMode: validated.displayMode,
        stats: {
          hull: 100,
          oxygen: 100,
          fuel: 100,
          food: 100,
          morale: 100,
          weirdness: 0
        },
        npcs: getInitialNpcs(),
        equippedItems: ['red_tape', 'universal_allen_key', 'nebula_freshener'], // Start with 3 items
        turns: [],
        currentActions: [],
        runningGags: [],
        eventHistory: [],
        interviewResponses: {},
        isComplete: false
      };

      // Generate Turn 0 introduction narrative
      const introNarrative = await generateIntroduction(initialState);
      const turn0: any = {
        turnNumber: 0,
        narrative: introNarrative,
        checks: [],
        delta: [],
        timestamp: Date.now()
      };
      initialState.turns.push(turn0);

      // AUTO-GENERATE SCENE IMAGE FOR TURN 0
      try {
        const templateName = selectImageTemplate(initialState);
        const imageResult = await generateImage(templateName, initialState);

        if (imageResult) {
          turn0.imageUrl = imageResult.imageUrl;
          turn0.imageTemplate = templateName;
        }
      } catch (imageError) {
        console.warn('Failed to auto-generate scene image for turn 0:', imageError);
        // Don't fail game start if image generation fails
      }

      // Generate initial actions
      const actions = await generateActions(initialState);
      initialState.currentActions = actions;

      await storage.createGameState(initialState);

      res.json(initialState);
    } catch (error) {
      console.error("Error starting game:", error);
      res.status(400).json({ error: "Failed to start game" });
    }
  });

  // Get game state
  app.get("/api/game/:id", async (req, res) => {
    try {
      const state = await storage.getGameState(req.params.id);
      if (!state) {
        return res.status(404).json({ error: "Game not found" });
      }
      res.json(state);
    } catch (error) {
      console.error("Error getting game:", error);
      res.status(500).json({ error: "Failed to get game" });
    }
  });

  // Take an action
  app.post("/api/game/action", async (req, res) => {
    try {
      const validated = actionInputSchema.parse(req.body);
      const state = await storage.getGameState(validated.gameId);

      if (!state) {
        return res.status(404).json({ error: "Game not found" });
      }

      if (state.isComplete) {
        return res.status(400).json({ error: "Game is already complete" });
      }

      // Find the selected action or create custom one
      let selectedAction = state.currentActions.find(a => a.action === validated.action);

      if (!selectedAction && validated.customText) {
        // Map custom text to intent
        const intent = await mapCustomActionToIntent(validated.customText) as Intent;
        selectedAction = {
          action: validated.customText,
          summary: "Custom action",
          risk: 'Risky',
          intent
        };
      }

      if (!selectedAction) {
        return res.status(400).json({ error: "Invalid action" });
      }

      // Increment turn
      state.turnNumber++;

      // Check for triggered events
      const triggeredEvents = getTriggeredEvents(state);
      const event = triggeredEvents[0]; // Take first triggered event

      // Determine skill check
      let skill = event ? event.skill : mapIntentToSkill(selectedAction.intent);
      let baseDC = event ? event.dc : getBaseDC(selectedAction.risk);
      const dc = calculateDC(baseDC, state.turnNumber, state.stats.morale);

      // Check for equipped item bonuses
      let skillBonus = 0;
      const equippedItems = state.equippedItems
        .map(id => getItemById(id))
        .filter((item): item is NonNullable<typeof item> => item !== undefined);

      for (const item of equippedItems) {
        if (item!.skillBonus && item!.skillBonus.skill === skill) {
          skillBonus += item!.skillBonus.bonus;
        }
      }

      // Check for NPC crew affinity bonuses
      for (const npc of state.npcs) {
        const npcSkills = NPC_SKILL_MAPPINGS[npc.name];
        if (npcSkills && npcSkills.includes(skill)) {
          // Affinity-based bonus:
          // +2 to +3 affinity = +2 bonus
          // +1 affinity = +1 bonus
          // 0 affinity = no bonus
          // -1 to -3 affinity = -1 penalty
          if (npc.affinity >= 2) {
            skillBonus += 2;
          } else if (npc.affinity === 1) {
            skillBonus += 1;
          } else if (npc.affinity <= -1) {
            skillBonus -= 1;
          }
        }
      }

      // Check for advantage (from items)
      const hasAdvantage = equippedItems.some(item => 
        item!.sceneEffect?.effect.includes('advantage') &&
        item!.sceneEffect?.effect.toLowerCase().includes(skill.toLowerCase())
      );

      // Roll dice (deterministic)
      const rng = new SeededRandom(state.seed);
      const roll1 = rng.rollD20(state.id, state.turnNumber, selectedAction.action);
      const roll2 = hasAdvantage ? rng.rollD20(state.id, state.turnNumber, selectedAction.action + '-adv') : 0;
      const rawRoll = hasAdvantage ? Math.max(roll1, roll2) : roll1;
      const finalRoll = rawRoll + skillBonus;
      const success = finalRoll >= dc;

      const checks = [{
        skill,
        dc,
        roll: finalRoll,
        success,
        description: ""
      }];

      // Generate narrative (pass event info if triggered)
      const narrative = await generateNarrative(
        state, 
        selectedAction.action, 
        checks,
        event ? { name: event.name, segment: event.segment, skill: event.skill } : null
      );

      // Calculate stat changes
      let deltaString = '';
      if (event) {
        deltaString = success ? event.passEffect : event.failEffect;
        if (event.id) {
          state.eventHistory.push(event.id);
        }
      } else {
        // Base consequences based on action risk
        deltaString = getActionConsequences(selectedAction, success);
      }

      // Apply item scene effects
      const sceneTags = event?.tags || getActionTags(selectedAction.intent);
      for (const item of equippedItems) {
        if (item!.sceneEffect) {
          const matchesTags = item!.sceneEffect.tags.some(tag => sceneTags.includes(tag));
          if (matchesTags) {
            const effectParts = item!.sceneEffect.effect.split('-');
            for (const part of effectParts) {
              if (part.match(/\w+[+-]\d+/)) {
                deltaString += `,${part}`;
              }
            }
          }
        }
      }

      const { stats: newStats, changes } = applyDelta(state.stats, deltaString);
      state.stats = newStats;

      // Advance day every 2 turns and apply daily consumption
      let consumptionChanges: any[] = [];
      if (state.turnNumber % 2 === 0) {
        state.day++;
        state.segment = getSegment(state.day);

        // Apply daily resource consumption
        const { deltaString: consumptionDelta } = calculateDailyConsumption(equippedItems);
        const { stats: statsAfterConsumption, changes: clampedChanges } = applyDelta(state.stats, consumptionDelta);
        state.stats = statsAfterConsumption;

        // Use clamped changes to ensure deltas match actual stat changes
        consumptionChanges = clampedChanges.map(change => ({
          ...change,
          note: 'Daily consumption'
        }));
      }

      // Check for NPC affinity changes
      updateNPCAffinities(state, skill, success);

      // Add running gag if this is a recurring event
      if (event && event.id && !state.runningGags.includes(event.name)) {
        state.runningGags.push(event.name);
      }

      // Create turn record with combined deltas (action effects + daily consumption)
      const turn: any = {
        turnNumber: state.turnNumber,
        narrative,
        checks,
        delta: [...changes, ...consumptionChanges],
        timestamp: Date.now()
      };
      state.turns.push(turn);

      // AUTO-GENERATE SCENE IMAGE
      try {
        const templateName = selectImageTemplate(state, event);
        const imageResult = await generateImage(templateName, state);

        if (imageResult) {
          turn.imageUrl = imageResult.imageUrl;
          turn.imageTemplate = templateName;
        }
      } catch (imageError) {
        console.warn('Failed to auto-generate scene image:', imageError);
        // Don't fail the turn if image generation fails
      }

      // Check for fail/win conditions
      const failReason = checkFailState(state.stats);
      if (failReason) {
        state.isComplete = true;
        state.failureReason = failReason;
      } else if (checkWinCondition(state)) {
        state.isComplete = true;
      }

      // Generate new actions for next turn
      if (!state.isComplete) {
        state.currentActions = await generateActions(state);
      }

      await storage.updateGameState(state.id, state);

      res.json(state);
    } catch (error) {
      console.error("Error processing action:", error);
      res.status(500).json({ error: "Failed to process action" });
    }
  });

  // Delete game (new voyage)
  app.delete("/api/game/:id", async (req, res) => {
    try {
      await storage.deleteGameState(req.params.id);
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting game:", error);
      res.status(500).json({ error: "Failed to delete game" });
    }
  });

  // Get all games for a username
  app.get("/api/games/user/:username", async (req, res) => {
    try {
      const games = await storage.getGamesByUsername(req.params.username);
      res.json(games);
    } catch (error) {
      console.error("Error fetching user games:", error);
      res.status(500).json({ error: "Failed to fetch user games" });
    }
  });

  // Prompt management endpoints
  app.get("/api/prompts", async (req, res) => {
    try {
      const prompts = await storage.getAllPromptTemplates();
      res.json(prompts);
    } catch (error) {
      console.error("Error fetching prompts:", error);
      res.status(500).json({ error: "Failed to fetch prompts" });
    }
  });

  app.get("/api/prompts/:name", async (req, res) => {
    try {
      const prompt = await storage.getActivePromptTemplate(req.params.name);
      if (!prompt) {
        return res.status(404).json({ error: "Prompt not found" });
      }
      res.json(prompt);
    } catch (error) {
      console.error("Error fetching prompt:", error);
      res.status(500).json({ error: "Failed to fetch prompt" });
    }
  });

  app.put("/api/prompts/:id", async (req, res) => {
    try {
      const { content, systemContent, inheritGlobalPrompt, description, active } = req.body;
      const updates: any = {};

      if (content !== undefined) updates.content = content;
      if (systemContent !== undefined) updates.systemContent = systemContent;
      if (inheritGlobalPrompt !== undefined) updates.inheritGlobalPrompt = inheritGlobalPrompt;
      if (description !== undefined) updates.description = description;
      if (active !== undefined) updates.active = active;

      const updated = await storage.updatePromptTemplate(req.params.id, updates);
      res.json(updated);
    } catch (error) {
      console.error("Error updating prompt:", error);
      res.status(500).json({ error: "Failed to update prompt" });
    }
  });

  app.post("/api/prompts/sync", async (req, res) => {
    try {
      await syncPromptsFromDatabase();
      const stats = getCacheStats();
      res.json({ 
        success: true, 
        message: "Prompts synchronized from database",
        ...stats
      });
    } catch (error) {
      console.error("Error syncing prompts:", error);
      res.status(500).json({ error: "Failed to sync prompts" });
    }
  });

  // Event management endpoints
  app.get("/api/events", async (req, res) => {
    try {
      const events = await storage.getAllEvents();
      res.json(events);
    } catch (error) {
