import CheckDisplay from './CheckDisplay';
import DeltaDisplay from './DeltaDisplay';
import ReactMarkdown from 'react-markdown';

interface Check {
  skill: string;
  dc: number;
  roll: number;
  success: boolean;
  description?: string;
}

interface DeltaChange {
  stat: string;
  change: number;
  note?: string;
}

interface TurnCardProps {
  turnNumber: number;
  narrative: string;
  checks?: Check[];
  delta: DeltaChange[];
  imageUrl?: string | null;
  imageTemplate?: string | null;
}

export default function TurnCard({ turnNumber, narrative, checks = [], delta, imageUrl, imageTemplate }: TurnCardProps) {
  return (
    <div className="mb-6 p-4 border border-[#00ffff] bg-[#001a1a]" data-testid={`turn-${turnNumber}`}>
      <div className="inline-block px-3 py-1 bg-[#00ffff] text-black text-xs font-bold mb-3" data-testid={`turn-badge-${turnNumber}`}>
        TURN {turnNumber}
      </div>
      <div className="space-y-3">
        {imageUrl && (
          <div className="overflow-hidden border-2 border-[#ff66ff]" data-testid={`turn-image-${turnNumber}`}>
            <img
              src={imageUrl}
              alt={`Scene visualization for turn ${turnNumber}`}
              className="w-full h-auto"
            />
            {imageTemplate && (
              <div className="p-2 bg-[#1a0a1a] text-xs text-[#ff66ff]">
                {imageTemplate}
              </div>
            )}
          </div>
        )}
        <div className="text-base leading-relaxed prose prose-sm max-w-none prose-invert text-[#00ffff]" data-testid={`narrative-${turnNumber}`}>
          <ReactMarkdown>{narrative}</ReactMarkdown>
