client/src/components/StatBar.tsx.content:
interface StatBarProps {
  label: string;
  value: number;
  max: number;
  icon: string;
  color?: string;
  dailyConsumption?: number;
}

export default function StatBar({ label, value, max, icon, color = "bg-primary", dailyConsumption }: StatBarProps) {
  const percentage = Math.max(0, Math.min(100, (value / max) * 100));
  const isLow = percentage < 30;
  const isCritical = percentage < 15;

  return (
    <div className="space-y-2" data-testid={`stat-${label.toLowerCase()}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-base" data-testid={`icon-${label.toLowerCase()}`}>{icon}</span>
          <span className="text-sm font-medium uppercase tracking-wide font-mono text-foreground">
            {label}
          </span>
          {dailyConsumption !== undefined && dailyConsumption > 0 && (
            <span className="text-xs text-muted-foreground font-mono" data-testid={`consumption-${label.toLowerCase()}`}>
              -{dailyConsumption}/day
            </span>
          )}
        </div>
        <span className={`text-lg font-bold tabular-nums font-mono ${isCritical ? 'text-destructive' : isLow ? 'text-yellow-600 dark:text-yellow-500' : 'text-foreground'}`} data-testid={`value-${label.toLowerCase()}`}>
          {value}/{max}
        </span>
      </div>
      <div className="h-2 rounded-full bg-muted overflow-hidden" data-testid={`bar-${label.toLowerCase()}`}>
        <div
          className={`h-full transition-all duration-300 rounded-full ${isCritical ? 'bg-destructive' : isLow ? 'bg-yellow-600 dark:bg-yellow-500' : color}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
}

