  --accent-border: hsl(from hsl(var(--accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  --destructive-border: hsl(var(--destructive));
  --destructive-border: hsl(from hsl(var(--destructive)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

@layer utilities {

  /* Hide ugly search cancel button in Chrome until we can style it properly */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  .no-default-hover-elevate {}

  .no-default-active-elevate {}

  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before {
    inset: -1px;
  }

  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }
}

/* ============================================
   TERMINAL EMULATOR MODE - CRT EFFECTS
   ============================================ */

/* Terminal Color Scheme - Green */
.terminal-mode {
  --terminal-bg: #000000;
  --terminal-fg: #00ff00;
  --terminal-glow: #00ff0088;
  --terminal-dim: #008800;
  --terminal-bright: #88ff88;
  --terminal-cursor: #00ff00;
}

/* Terminal Color Scheme - Amber */
.terminal-mode-amber {
  --terminal-bg: #000000;
  --terminal-fg: #ffb000;
  --terminal-glow: #ffb00088;
  --terminal-dim: #cc8800;
  --terminal-bright: #ffd700;
  --terminal-cursor: #ffb000;
}

/* CRT Screen Container */
.terminal-screen {
  position: relative;
  background: var(--terminal-bg);
  color: var(--terminal-fg);
  font-family: 'Courier New', 'Consolas', monospace;
  overflow: hidden;
  text-shadow: 0 0 5px var(--terminal-glow);
}

/* Scanlines Effect */
.terminal-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.15),
    rgba(0, 0, 0, 0.15) 1px,
    transparent 1px,
    transparent 2px
  );
  pointer-events: none;
  z-index: 10;
}

/* Phosphor Glow Overlay */
.terminal-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse at center,
    transparent 0%,
    rgba(0, 0, 0, 0.3) 100%
  );
  pointer-events: none;
  z-index: 11;
}

/* Screen Flicker Animation */
@keyframes flicker {
  0% { opacity: 0.97; }
  2% { opacity: 0.95; }
  4% { opacity: 0.98; }
  8% { opacity: 0.96; }
  10% { opacity: 0.97; }
  12% { opacity: 0.99; }
  14% { opacity: 0.98; }
  16% { opacity: 0.97; }
  18% { opacity: 0.96; }
  20% { opacity: 0.98; }
  100% { opacity: 0.97; }
}

.terminal-screen {
  animation: flicker 0.15s infinite alternate;
}

/* CRT Curvature Effect */
.terminal-screen-wrapper {
  position: relative;
  perspective: 1000px;
}

.terminal-screen-curved {
  transform: rotateX(0.5deg);
  border-radius: 8px;
  box-shadow: 
    inset 0 0 100px var(--terminal-glow),
    0 0 50px rgba(0, 0, 0, 0.8);
}

/* Cursor Blink Animation */
@keyframes cursor-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.terminal-cursor {
  display: inline-block;
  width: 0.6em;
  height: 1.2em;
  background: var(--terminal-cursor);
  margin-left: 2px;
  animation: cursor-blink 1s infinite;
  box-shadow: 0 0 5px var(--terminal-glow);
}

/* Typewriter Effect */
@keyframes typewriter {
  from { width: 0; }
  to { width: 100%; }
}

.terminal-typewriter {
  overflow: hidden;
  white-space: nowrap;
  border-right: 2px solid var(--terminal-cursor);
  animation: 
    typewriter 2s steps(40) forwards,
    cursor-blink 0.75s step-end infinite;
}

/* Terminal Text Styles */
.terminal-text {
  color: var(--terminal-fg);
  text-shadow: 0 0 5px var(--terminal-glow);
  line-height: 1.5;
}

.terminal-text-dim {
  color: var(--terminal-dim);
  text-shadow: 0 0 3px var(--terminal-dim);
}

.terminal-text-bright {
  color: var(--terminal-bright);
  text-shadow: 0 0 8px var(--terminal-glow);
  font-weight: bold;
}

/* Terminal Input Field */
.terminal-input {
  background: transparent;
  border: none;
  color: var(--terminal-fg);
  font-family: 'Courier New', 'Consolas', monospace;
  outline: none;
  caret-color: var(--terminal-cursor);
  text-shadow: 0 0 5px var(--terminal-glow);
}

.terminal-input::placeholder {
  color: var(--terminal-dim);
  opacity: 0.6;
}

/* Terminal Prompt */
.terminal-prompt {
  color: var(--terminal-bright);
  text-shadow: 0 0 8px var(--terminal-glow);
  font-weight: bold;
}

/* ASCII Border */
.terminal-border {
  border: 2px solid var(--terminal-fg);
  box-shadow: 
    0 0 10px var(--terminal-glow),
    inset 0 0 10px var(--terminal-glow);
}

/* Chromatic Aberration Effect */
.terminal-chromatic {
  position: relative;
}

.terminal-chromatic::before {
  content: attr(data-text);
  position: absolute;
  left: -1px;
  color: #ff00ff;
  opacity: 0.3;
  pointer-events: none;
}

.terminal-chromatic::after {
  content: attr(data-text);
  position: absolute;
  left: 1px;
  color: #00ffff;
  opacity: 0.3;
  pointer-events: none;
}

/* CRT Static/Noise (subtle) */
@keyframes static-noise {
  0% { background-position: 0 0; }
  100% { background-position: 100% 100%; }
}

.terminal-static {
  position: relative;
}

.terminal-static::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' /%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.05'/%3E%3C/svg%3E");
  opacity: 0.02;
  pointer-events: none;
  animation: static-noise 0.2s infinite;
  z-index: 12;
}

/* Terminal Command List */
.terminal-command-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.terminal-command-item {
  padding: 0.25rem 0;
  color: var(--terminal-fg);
  text-shadow: 0 0 5px var(--terminal-glow);
  cursor: pointer;
  transition: all 0.1s ease;
}

.terminal-command-item:hover {
  color: var(--terminal-bright);
  text-shadow: 0 0 10px var(--terminal-glow);
  padding-left: 1rem;
}

/* Terminal Loading Spinner */
@keyframes terminal-spin {
  0% { content: '|'; }
  25% { content: '/'; }
  50% { content: '—'; }
  75% { content: '\\'; }
  100% { content: '|'; }
}

.terminal-spinner::after {
  content: '|';
  animation: terminal-spin 0.5s infinite;
  margin-left: 0.5rem;
}

/* Screen Power-On Effect */
@keyframes power-on {
  0% {
    transform: scaleY(0.001) scaleX(1);
    opacity: 0;
  }
  50% {
    transform: scaleY(0.01) scaleX(1);
    opacity: 0.5;
  }
  100% {
    transform: scaleY(1) scaleX(1);
    opacity: 1;
  }
}

.terminal-power-on {
  animation: power-on 0.5s ease-out;
}

