  name: string;
  description: string;
  icon: string;
  skillBonus: any | null;
  sceneEffect: any | null;
  tags: string | null;
  active: number;
}

interface CompactStatProps {
  icon: React.ComponentType<{ className?: string }>;
  value: number;
  max: number;
  label: string;
}

function CompactStat({ icon: Icon, value, max, label }: CompactStatProps) {
  const percentage = Math.max(0, Math.min(100, (value / max) * 100));
  const isCritical = percentage < 15;
  const isLow = percentage < 30;

  return (
    <div className="flex flex-col items-center gap-1 min-w-0" data-testid={`compact-stat-${label.toLowerCase()}`}>
      <Icon className={`w-4 h-4 ${isCritical ? 'text-red-500' : isLow ? 'text-yellow-500' : 'text-[#00ffff]'}`} data-testid={`compact-icon-${label.toLowerCase()}`} />
      <span className="text-[10px] font-mono text-[#00aaaa] uppercase tracking-tight" data-testid={`compact-label-${label.toLowerCase()}`}>
        {label}
      </span>
      <div className="w-full h-1.5 rounded-full bg-[#001a1a] overflow-hidden border border-[#00aaaa]">
        <div
          className={`h-full transition-all duration-300 ${isCritical ? 'bg-red-600' : isLow ? 'bg-yellow-600' : 'bg-cyan-600'}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
      <span className={`text-xs font-mono font-bold tabular-nums ${isCritical ? 'text-red-500' : isLow ? 'text-yellow-500' : 'text-[#00ffff]'}`} data-testid={`compact-value-${label.toLowerCase()}`}>
        {value}
      </span>
    </div>
  );
}

export default function GamePage() {
  const params = useParams();
  const gameId = params.gameId || null;
  const [, setLocation] = useLocation();
  const [showSettings, setShowSettings] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [customAction, setCustomAction] = useState('');
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [imagePromptUsed, setImagePromptUsed] = useState<string | null>(null);
  const [showPreviousTurns, setShowPreviousTurns] = useState(true);
  const [currentActionText, setCurrentActionText] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();
  const isMobile = useIsMobile();

  // Redirect to menu if no gameId
  useEffect(() => {
    if (!gameId) {
      setLocation('/menu');
    }
  }, [gameId, setLocation]);

  // Fetch items from API
  const { data: items = [] } = useQuery<Item[]>({
    queryKey: ['/api/items'],
  });

  // Fetch game state
  const { data: gameState, isLoading } = useQuery<GameState>({
    queryKey: [`/api/game/${gameId}`],
    enabled: !!gameId,
    refetchInterval: false
  });

  // Take action mutation
  const actionMutation = useMutation({
    mutationFn: async ({ action, customText }: { action: string; customText?: string }) => {
      const response = await apiRequest('POST', '/api/game/action', {
        gameId,
        action,
        customText
      });
      return await response.json();
    },
    onSuccess: (data: GameState) => {
      queryClient.setQueryData([`/api/game/${gameId}`], data);
      setCustomAction('');
      setShowCustomInput(false);
      setCurrentActionText(null);
      setGeneratedImage(null);
      setImagePromptUsed(null);

      // Check for game end
      if (data.isComplete) {
        if (data.failureReason) {
          toast({
            title: "Mission Failed",
            description: data.failureReason,
            variant: "destructive"
          });
        } else {
          toast({
            title: "Mission Complete!",
            description: "You made it to Uranus!"
          });
        }
      }
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to process action",
        variant: "destructive"
      });
    }
  });

  const generateImageMutation = useMutation({
    mutationFn: async ({ templateName, gameId: gId }: { templateName: string; gameId: string }) => {
      const response = await apiRequest('POST', '/api/generate-image', {
        templateName,
        gameId: gId
      });
      return await response.json();
    },
    onSuccess: (data: { imageUrl: string; promptUsed: string }) => {
      setGeneratedImage(data.imageUrl);
      setImagePromptUsed(data.promptUsed);
      toast({
        title: "Image Generated",
        description: "Scene has been visualized"
      });
    },
    onError: () => {
      toast({
        title: "Image Generation Failed",
        description: "Unable to generate image. Please try again.",
        variant: "destructive"
      });
    }
  });

  // Auto-scroll to top when new turn is added
  useEffect(() => {
    if (scrollRef.current && gameState?.turns.length) {
      scrollRef.current.scrollTop = 0;
    }
  }, [gameState?.turns.length]);

  const handleActionClick = (action: string) => {
    if (!gameId || actionMutation.isPending) return;
    setCurrentActionText(action);

    // Scroll to top
    if (isMobile) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (scrollRef.current) {
      scrollRef.current.scrollTop = 0;
    }

    actionMutation.mutate({ action });
  };

  const handleCustomAction = () => {
    if (!gameId || !customAction.trim() || actionMutation.isPending) return;
    setCurrentActionText(customAction);

    // Scroll to top
    if (isMobile) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (scrollRef.current) {
      scrollRef.current.scrollTop = 0;
    }

    actionMutation.mutate({ action: customAction, customText: customAction });
  };

  const handleBackToMenu = () => {
    setLocation('/menu');
  };

  const toggleItem = (itemId: string) => {
    if (!gameState) return;

    const equipped = gameState.equippedItems;
    const isEquipped = equipped.includes(itemId);

    if (isEquipped) {
      const newEquipped = equipped.filter(id => id !== itemId);
      queryClient.setQueryData([`/api/game/${gameId}`], {
        ...gameState,
        equippedItems: newEquipped
      });
    } else if (equipped.length < 3) {
      queryClient.setQueryData([`/api/game/${gameId}`], {
        ...gameState,
        equippedItems: [...equipped, itemId]
      });
    } else {
      toast({
        title: "Maximum Items Equipped",
        description: "You can only equip 3 items at once.",
        variant: "destructive"
      });
    }
  };

  const itemIcon = (itemId: string) => {
    return items.find((i: Item) => i.id === itemId)?.icon || '';
  };

  // Loading state
  if (!gameId || isLoading || !gameState) {
    return (
      <div className="relative min-h-screen bg-black flex items-center justify-center font-mono">
        <CRTBackground intensity="low" />
        <div className="relative z-10">
          <Loader2 className="w-8 h-8 animate-spin text-[#00ffff]" />
        </div>
      </div>
    );
  }

  // Main game view
  return (
    <div className="relative min-h-screen bg-black font-mono text-[#00ffff]">
      <CRTBackground intensity="low" />

      <div
        className="absolute inset-0 bg-cover bg-center bg-fixed opacity-20"
        style={{ backgroundImage: `url(${spaceBackground})` }}
      />

      <div className="relative z-10 min-h-screen">
        <header className="sticky top-0 z-50 border-b-2 border-[#00ffff] bg-black/90 backdrop-blur-md shadow-[0_0_20px_#00ffff]">
          <div className="container mx-auto px-3 sm:px-4 py-2 sm:py-3">
            <div className="flex items-center justify-between gap-2">
              <div className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-4 min-w-0">
                <h1 className={`${isMobile ? 'text-lg' : 'text-2xl'} font-bold text-[#00ffff] drop-shadow-[0_0_10px_#00ffff] truncate`} data-testid="game-title">
                  {isMobile ? 'QUEST 4 URANUS' : '█ QUEST 4 URANUS █'}
                </h1>
                <div className={`${isMobile ? 'text-xs' : 'text-sm'} text-[#ffaa00] whitespace-nowrap`} data-testid="game-meta">
                  DAY {gameState.day} • {gameState.segment.toUpperCase()}
                </div>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2 flex-shrink-0">
                {!isMobile && (
                  <Link href="/dev">
                    <Button
                      variant="outline"
                      size="icon"
                      className="border-[#00aaaa] text-[#00aaaa]"
                      data-testid="button-dev-tools"
                    >
                      <Code2 className="w-5 h-5" />
                    </Button>
                  </Link>
                )}
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => setShowHelp(true)}
                  className="border-[#ffaa00] text-[#ffaa00] hover:bg-[#1a1000] hover:shadow-[0_0_20px_#ffaa00] transition-all"
                  data-testid="button-help"
                  title="How to Probe Uranus"
                >
                  <HelpCircle className={`${isMobile ? 'w-4 h-4' : 'w-5 h-5'}`} />
                </Button>
                <Button
                  variant="outline"
                  size={isMobile ? "icon" : "sm"}
                  onClick={handleBackToMenu}
                  className="border-[#00ffff] text-[#00ffff]"
                  data-testid="button-back-to-menu"
                >
                  <RotateCcw className={`${isMobile ? 'w-4 h-4' : 'w-4 h-4 mr-2'}`} />
                  {!isMobile && 'MENU'}
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => setShowSettings(true)}
                  className="border-[#00aaaa] text-[#00aaaa]"
                  data-testid="button-settings"
                >
                  <Settings className={`${isMobile ? 'w-4 h-4' : 'w-5 h-5'}`} />
                </Button>
              </div>
            </div>
          </div>
        </header>

        <div className="container mx-auto px-3 sm:px-4 py-4 sm:py-6">
          <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-4 sm:gap-6">
            <aside className="order-2 lg:order-1 space-y-4 sm:space-y-6">
              <div className="p-6 border-2 border-[#00ffff] bg-[#001a1a] shadow-[0_0_20px_#00ffff] space-y-4" data-testid="stats-panel">
                <h2 className="text-lg font-bold text-[#ffaa00]">[ SHIP STATUS ]</h2>
                <StatBar label="Hull" value={gameState.stats.hull} max={100} icon="🚀" color="bg-blue-600" />
                <StatBar label="Oxygen" value={gameState.stats.oxygen} max={100} icon="💨" color="bg-cyan-600" dailyConsumption={3} />
                <StatBar label="Fuel" value={gameState.stats.fuel} max={100} icon="⛽" color="bg-amber-600" dailyConsumption={4} />
                <StatBar label="Food" value={gameState.stats.food} max={100} icon="🍔" color="bg-green-600" dailyConsumption={3} />
                <StatBar label="Morale" value={gameState.stats.morale} max={100} icon="❤️" color="bg-pink-600" dailyConsumption={2} />
                <div className="pt-2">
                  <WeirdnessMeter value={gameState.stats.weirdness} />
                </div>
              </div>

              <div className="p-6 border-2 border-[#ff66ff] bg-[#1a0a1a] shadow-[0_0_20px_#ff66ff] space-y-4" data-testid="crew-panel">
                <h2 className="text-lg font-bold text-[#ffaa00]">[ CREW ]</h2>
                <div className="space-y-3">
                  {gameState.npcs.map(npc => (
                    <NPCCard
                      key={npc.id}
                      name={npc.name}
                      role={npc.role}
                      affinity={npc.affinity}
                      status={npc.status}
                      lastInteraction={npc.lastInteraction}
                    />
                  ))}
                </div>
              </div>

              <div className="p-6 border-2 border-[#ffaa00] bg-[#1a1000] shadow-[0_0_20px_#ffaa00] space-y-4" data-testid="items-panel">
                <h2 className="text-lg font-bold text-[#ffaa00]">
                  [ ITEMS ({gameState.equippedItems.length}/3) ]
                </h2>
                <div className="space-y-2">
                  {items.map((item: Item) => (
                    <ItemCard
                      key={item.id}
                      name={item.name}
                      description={item.description}
                      icon={item.icon}
                      equipped={gameState.equippedItems.includes(item.id)}
                      onToggle={() => toggleItem(item.id)}
                    />
                  ))}
                </div>
              </div>
            </aside>

            <main className="order-1 lg:order-2 space-y-4 sm:space-y-6">
              {isMobile && (
                <div className="p-3 border-2 border-[#ffaa00] bg-[#1a1000] shadow-[0_0_15px_#ffaa00]" data-testid="compact-stats-summary">
                  <h3 className="text-xs font-bold text-[#ffaa00] uppercase mb-2">Ship Status</h3>
                  <div className="grid grid-cols-5 gap-2 mb-3">
                    <CompactStat icon={Rocket} value={gameState.stats.hull} max={100} label="Hull" />
                    <CompactStat icon={Wind} value={gameState.stats.oxygen} max={100} label="O2" />
                    <CompactStat icon={Fuel} value={gameState.stats.fuel} max={100} label="Fuel" />
                    <CompactStat icon={UtensilsCrossed} value={gameState.stats.food} max={100} label="Food" />
                    <CompactStat icon={Heart} value={gameState.stats.morale} max={100} label="Morale" />
                  </div>
                  <div className="pt-2 border-t border-[#ffaa00]/30">
                    <WeirdnessMeter value={gameState.stats.weirdness} />
                  </div>
                </div>
              )}
              <div
                ref={scrollRef}
                className={`p-4 sm:p-6 border-2 border-[#00ffff] bg-[#000a0a] shadow-[0_0_15px_#00ffff] ${isMobile ? '' : 'overflow-y-auto min-h-[600px] max-h-[600px]'}`}
                data-testid="narrative-feed"
              >
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-lg font-bold text-[#ffaa00]">[ MISSION VIEWSCREEN ]</h2>
                  {gameState.turns.length > 0 && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => generateImageMutation.mutate({
                        templateName: 'general_scene',
                        gameId: gameId!
                      })}
                      disabled={generateImageMutation.isPending}
                      className="border-[#00aaaa] text-[#00aaaa]"
                      data-testid="button-generate-image"
                    >
                      {generateImageMutation.isPending ? (
                        <>
                          <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                          GENERATING...
                        </>
                      ) : (
                        <>
                          <ImageIcon className="w-4 h-4 mr-2" />
                          VISUALIZE
                        </>
                      )}
                    </Button>
                  )}
                </div>

                {gameState.turns.length === 0 ? (
                  <p className="text-[#00aaaa] italic">
                    &gt; Select an action below to begin your journey to Uranus...
                  </p>
                ) : (
                  <>
                    {actionMutation.isPending && (
                      <div className="mb-6 p-4 border-2 border-[#00ffff] bg-[#001a1a] animate-pulse shadow-[0_0_20px_#00ffff]" data-testid="loading-indicator">
                        <div className="flex items-center gap-2">
                          <Loader2 className="h-4 w-4 animate-spin text-[#00ffff]" />
                          <div className="flex flex-col gap-1">
                            <span className="text-sm text-[#00ffff] font-bold">PROCESSING ACTION...</span>
                            {currentActionText && (
                              <span className="text-xs text-[#ffaa00] italic" data-testid="current-action-text">
                                "{currentActionText}"
                              </span>
                            )}
                            <span className="text-xs text-[#00aaaa]">Generating scene visualization...</span>
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Current Turn Section */}
                    <div className="mb-6">
                      <div className="mb-4 pb-2 border-b-2 border-[#ffaa00]">
                        <h3 className="text-lg font-bold text-[#ffaa00]">[ CURRENT MISSION STATUS ]</h3>
                      </div>
                      <TurnCard
                        key={gameState.turns[gameState.turns.length - 1].turnNumber}
                        {...gameState.turns[gameState.turns.length - 1]}
                        imageUrl={generatedImage || gameState.turns[gameState.turns.length - 1].imageUrl}
                        imageTemplate={
                          generatedImage
                            ? `Manual: ${imagePromptUsed || 'Unknown'}`
                            : gameState.turns[gameState.turns.length - 1].imageTemplate
                        }
                      />
                    </div>

                    {/* Previous Turns Section */}
                    {gameState.turns.length > 1 && (
                      <div>
                        <div className="mb-4 pb-2 border-b-2 border-[#00aaaa] flex items-center justify-between">
                          <h3 className="text-lg font-bold text-[#00aaaa]">[ PREVIOUS TRANSMISSIONS ]</h3>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setShowPreviousTurns(!showPreviousTurns)}
                            className="text-[#00aaaa] hover:text-[#00ffff]"
                            data-testid="button-toggle-previous-turns"
                          >
                            {showPreviousTurns ? (
                              <>
                                <ChevronUp className="w-4 h-4 mr-1" />
                                HIDE ({gameState.turns.length - 1})
                              </>
                            ) : (
                              <>
                                <ChevronDown className="w-4 h-4 mr-1" />
                                SHOW ({gameState.turns.length - 1})
                              </>
                            )}
                          </Button>
                        </div>
                        {showPreviousTurns && (
                          <div data-testid="previous-turns-section">
                            {gameState.turns.slice(0, -1).reverse().map((turn) => (
                              <TurnCard
                                key={turn.turnNumber}
                                {...turn}
                              />
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </>
                )}
              </div>

              {!gameState.isComplete && (
                <div className={`${isMobile ? 'p-3' : 'p-4'} border-2 border-[#00ffff] bg-[#000a0a] shadow-[0_0_15px_#00ffff]`} data-testid="actions-panel">
                  <div className="flex items-center justify-between mb-3 sm:mb-4">
                    <h2 className={`${isMobile ? 'text-base' : 'text-lg'} font-bold text-[#ffaa00]`}>[ ACTIONS ]</h2>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setShowCustomInput(!showCustomInput)}
                      className="border-[#00aaaa] text-[#00aaaa] text-xs"
                      data-testid="button-custom-action"
                    >
                      {showCustomInput ? 'SUGGESTIONS' : 'CUSTOM'}
                    </Button>
                  </div>

                  {showCustomInput ? (
                    <div className="flex gap-2">
                      <Input
                        placeholder="Describe your action..."
                        value={customAction}
                        onChange={(e) => setCustomAction(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleCustomAction()}
                        disabled={actionMutation.isPending}
                        className="border-[#00ffff] bg-[#001a1a] text-[#00ffff] placeholder:text-[#006666]"
                        data-testid="input-custom-action"
                      />
                      <Button
                        variant="outline"
                        size="icon"
                        onClick={handleCustomAction}
                        disabled={actionMutation.isPending || !customAction.trim()}
                        className="border-[#00ffff] text-[#00ffff] flex-shrink-0"
                        data-testid="button-submit-custom"
                      >
                        <Send className="w-4 h-4" />
                      </Button>
                    </div>
                  ) : (
                    <div className={`flex flex-wrap ${isMobile ? 'gap-2' : 'gap-3'}`} data-testid="action-chips">
                      {gameState.currentActions.map((action, i) => (
                        <ActionChip
                          key={i}
                          {...action}
                          itemIcon={action.usesItemId ? itemIcon(action.usesItemId) : undefined}
                          onClick={() => handleActionClick(action.action)}
                        />
                      ))}
                    </div>
                  )}
                </div>
              )}

              {gameState.isComplete && (
                <div className="p-6 border-2 border-[#ff66ff] bg-[#1a0a1a] shadow-[0_0_20px_#ff66ff] text-center" data-testid="game-complete">
                  <h2 className="text-2xl font-bold text-[#ff66ff] mb-2">
                    {gameState.failureReason ? '[ MISSION FAILED ]' : '[ MISSION COMPLETE! ]'}
                  </h2>
                  <p className="text-[#00aaaa] mb-4">
                    {gameState.failureReason || 'You successfully reached Uranus!'}
                  </p>
                  <Button
                    variant="outline"
                    onClick={handleBackToMenu}
                    className="border-2 border-[#00ffff] text-[#00ffff]"
                    data-testid="button-new-voyage"
                  >
                    RETURN TO MENU
                  </Button>
                </div>
              )}
            </main>
          </div>
        </div>

        <Dialog open={showHelp} onOpenChange={setShowHelp}>
          <DialogContent className="max-w-4xl max-h-[90vh] p-0 bg-black border-2 border-[#00ffff] shadow-[0_0_20px_#00ffff]" data-testid="help-dialog">
            <DialogHeader className="px-6 py-4 border-b-2 border-[#00ffff] bg-black/90">
              <DialogTitle className="text-xl font-bold text-[#00ffff] font-mono drop-shadow-[0_0_10px_#00ffff]">
                HOW TO PROBE URANUS
              </DialogTitle>
              <DialogDescription className="text-[#00aaaa] font-mono">
                Everything you need to know about your mission to Uranus
              </DialogDescription>
            </DialogHeader>
            <ScrollArea className="max-h-[calc(90vh-120px)] px-6 py-4 font-mono text-[#00ffff]">
              <HelpContent />
            </ScrollArea>
          </DialogContent>
        </Dialog>

        <Dialog open={showSettings} onOpenChange={setShowSettings}>
          <DialogContent data-testid="settings-dialog">
            <DialogHeader>
              <DialogTitle>Game Settings</DialogTitle>
              <DialogDescription>
                View and adjust game parameters
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-6 py-4">
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium">Absurdity Dial</label>
                  <span className="text-sm font-mono font-bold text-primary">{gameState.absurdity}</span>
                </div>
                <div className="text-xs text-muted-foreground space-y-1">
                  <div>0: Dry wit, minimal chaos</div>
                  <div>1: Balanced humor</div>
                  <div>2: Frequent bureaucracy (default)</div>
                  <div>3: Maximum cosmic chaos</div>
                </div>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

client/src/components/ItemCard.tsx.content:
interface ItemCardProps {
  name: string;
  description: string;
  icon: string;
  equipped: boolean;
  onToggle?: () => void;
}

export default function ItemCard({ name, description, icon, equipped, onToggle }: ItemCardProps) {
  return (
    <button
      className={`p-3 border-2 text-left transition-all ${
        equipped
          ? 'border-[#ffaa00] bg-[#1a1000] shadow-[0_0_10px_#ffaa00]'
          : 'border-[#00aaaa] bg-[#0a0a0a] hover:bg-[#001a1a]'
      }`}
      onClick={onToggle}
      data-testid={`item-${name.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <div className="flex items-start gap-3">
        <span className="text-2xl flex-shrink-0" data-testid="item-icon">{icon}</span>
        <div className="flex-1 min-w-0">
          <h4 className={`font-semibold text-sm truncate ${equipped ? 'text-[#ffaa00]' : 'text-[#00ffff]'}`} data-testid="item-name">
            {name}
          </h4>
          <p className="text-xs text-[#00aaaa] line-clamp-2" data-testid="item-description">
            {description}
          </p>
          {equipped && (
            <span className="inline-block mt-1 text-xs font-bold text-[#ffaa00]" data-testid="item-equipped-badge">
              [EQUIPPED]
            </span>
          )}
        </div>
      </div>
    </button>
  );
}

client/src/components/ui/toast.tsx.content:
import * as React from "react"
import * as ToastPrimitives from "@radix-ui/react-toast"
import { cva, type VariantProps } from "class-variance-authority"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"

const ToastProvider = ToastPrimitives.Provider

const ToastViewport = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Viewport>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Viewport>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Viewport
    ref={ref}
    className={cn(
      "fixed top-0 z-[100] flex max-h-screen w-full flex-col-reverse p-4 sm:bottom-0 sm:right-0 sm:top-auto sm:flex-col md:max-w-[420px]",
      className
    )}
    {...props}
  />
))
ToastViewport.displayName = ToastPrimitives.Viewport.displayName

const toastVariants = cva(
  "group pointer-events-auto relative flex w-full items-center justify-between space-x-4 overflow-hidden rounded-md border p-6 pr-8 shadow-lg transition-all data-[swipe=cancel]:translate-x-0 data-[swipe=end]:translate-x-[var(--radix-toast-swipe-end-x)] data-[swipe=move]:translate-x-[var(--radix-toast-swipe-move-x)] data-[swipe=move]:transition-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[swipe=end]:animate-out data-[state=closed]:fade-out-80 data-[state=closed]:slide-out-to-right-full data-[state=open]:slide-in-from-top-full data-[state=open]:sm:slide-in-from-bottom-full",
  {
    variants: {
      variant: {
        default: "border bg-background text-foreground",
        destructive:
          "destructive group border-destructive bg-destructive text-destructive-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

const Toast = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Root>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Root> &
    VariantProps<typeof toastVariants>
>(({ className, variant, ...props }, ref) => {
  return (
    <ToastPrimitives.Root
      ref={ref}
      className={cn(toastVariants({ variant }), className)}
      {...props}
    />
  )
})
Toast.displayName = ToastPrimitives.Root.displayName

const ToastAction = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Action>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Action>
