import OpenAI from "openai";
import type { GameState, ActionChip } from "@shared/schema";
import { storage } from "./storage.js";
import { getItemById } from "./itemCache";
import { getPromptFromCache } from "./promptCache.js";
import { getImagePromptByName } from "./imagePromptCache";
import { saveImageToFile, loadImageFromFile, deleteImageFile } from "./imageStorage.js";
import { 
  generatePromptHash, 
  generateVariablesHash, 
  generateCacheKey, 
  generateSceneFingerprint,
  calculateSceneSimilarity,
  findSimilarScenes,
  type ImageSettings,
  type SceneFingerprint
} from "./cacheUtils.js";

// Text generation client (via Replit AI Integration)
const openai = new OpenAI({
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY
});

// Image generation client (direct to OpenAI API)
const openaiImages = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

const absurdityDescriptions = [
  "Dry wit, minimal chaos, professional space opera",
  "Balanced humor with occasional juvenile moments",
  "Frequent bureaucratic absurdity with clear innuendo (default)",
  "Maximum cosmic chaos while staying PG-13"
];

function replaceVariables(template: string, variables: Record<string, any> = {}): string {
  let result = template;

  for (const [key, value] of Object.entries(variables)) {
    const regex = new RegExp(`\\{\\{${key}\\}\\}`, 'g');
    result = result.replace(regex, String(value));
  }

  return result;
}

function addInterviewResponsesToVariables(variables: Record<string, any>, state: GameState): Record<string, any> {
  const enhanced = { ...variables };

  if (state.interviewResponses && typeof state.interviewResponses === 'object') {
    for (const [key, value] of Object.entries(state.interviewResponses)) {
      enhanced[`INTERVIEW_${key}`] = value || 'Not provided';
    }
  }

  return enhanced;
}

async function logLlmCall(
  functionName: string,
  prompt: string,
  response: string,
  metadata: any = {},
  executionTimeMs: number,
  gameId?: string,
  turnNumber?: number
) {
  try {
    await storage.createLlmLog({
      functionName,
      prompt,
      response,
      metadata,
      executionTimeMs,
      gameId: gameId || null,
      turnNumber: turnNumber || null,
      promptTemplateId: null,
    });
  } catch (error) {
    console.error("Error logging LLM call:", error);
  }
}

export async function generateIntroduction(state: GameState): Promise<string> {
  const startTime = Date.now();

  try {
    const equippedItems = state.equippedItems
      .map(id => getItemById(id))
      .filter((item): item is NonNullable<typeof item> => item !== undefined)
      .map(i => `${i.name} (${i.icon})`);

    const npcSummary = state.npcs.map(npc => 
      `${npc.name} (${npc.role})`
    ).join(', ');

    const promptTemplate = getPromptFromCache('intro_generation');

    let variables: Record<string, any> = {
      HULL: state.stats.hull,
      OXYGEN: state.stats.oxygen,
      FUEL: state.stats.fuel,
      FOOD: state.stats.food,
      MORALE: state.stats.morale,
      EQUIPPED_ITEMS: equippedItems.join(', ') || 'None',
      NPC_SUMMARY: npcSummary,
      ABSURDITY_DESCRIPTION: absurdityDescriptions[state.absurdity]
    };

    variables = addInterviewResponsesToVariables(variables, state);

    const systemPrompt = replaceVariables(promptTemplate.system, variables);
    const userPrompt = replaceVariables(promptTemplate.user, variables);

    const response = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ],
      max_completion_tokens: 400
    });

    const narrative = response.choices[0].message.content || "The docking bay buzzes with pre-departure chaos as your ship awaits its most underqualified captain yet. You.";
    const executionTime = Date.now() - startTime;

    await logLlmCall(
      'generateIntroduction',
      `SYSTEM:\n${systemPrompt}\n\nUSER:\n${userPrompt}`,
      narrative,
      { model: 'gpt-4o-mini', variables },
      executionTime,
      state.id,
      0
    );

    return narrative;
  } catch (error) {
    console.error("Error generating introduction:", error);
    const executionTime = Date.now() - startTime;
    const errorMessage = "The docking bay hums with anticipation. Your ship awaits, ready to depart for the outer reaches. The crew eyes you skeptically. The coffee machine has already filed three grievances.";

    await logLlmCall(
      'generateIntroduction',
      `Error: ${error}`,
      errorMessage,
      { error: String(error), fallback: true },
      executionTime,
      state.id,
      0
    );

    return errorMessage;
  }
}

export async function generateNarrative(
  state: GameState,
  playerAction: string,
  checks: any[],
  triggeredEvent?: { name: string; segment: string; skill: string } | null
): Promise<string> {
  const startTime = Date.now();

  try {
    const recentTurns = state.turns.slice(-3).map(t => 
      `Turn ${t.turnNumber}: ${t.narrative.substring(0, 150)}...`
    ).join('\n');

    const equippedItems = state.equippedItems
      .map(id => getItemById(id))
      .filter((item): item is NonNullable<typeof item> => item !== undefined)
      .map(i => `${i.name} (${i.icon})`);

    const npcSummary = state.npcs.map(npc => 
      `${npc.name}: ${npc.affinity > 0 ? 'Warm' : npc.affinity < 0 ? 'Cold' : 'Neutral'} (${npc.status})`
    ).join(', ');

    const checksText = checks.map(c => 
      `- ${c.skill} DC${c.dc}: Rolled ${c.roll} ${c.success ? '✅ SUCCESS' : '❌ FAIL'}`
    ).join('\n');

    const triggeredEventText = triggeredEvent 
      ? `${triggeredEvent.name} (${triggeredEvent.segment} segment - ${triggeredEvent.skill} challenge)`
      : 'No special events triggered this turn';

    const promptTemplate = getPromptFromCache('turn_generation');

    let variables: Record<string, any> = {
      TURN_NUMBER: state.turnNumber + 1,
      DAY: state.day,
      SEGMENT: state.segment,
      HULL: state.stats.hull,
      OXYGEN: state.stats.oxygen,
      FUEL: state.stats.fuel,
      FOOD: state.stats.food,
      MORALE: state.stats.morale,
      WEIRDNESS: state.stats.weirdness,
      EQUIPPED_ITEMS: equippedItems.join(', ') || 'None',
      NPC_SUMMARY: npcSummary,
      PLAYER_ACTION: playerAction,
      CHECKS: checksText,
      RECENT_TURNS: recentTurns || 'This is the first turn.',
      RUNNING_GAGS: state.runningGags.slice(0, 3).join(', ') || 'None yet',
      TRIGGERED_EVENT: triggeredEventText,
      ABSURDITY_DESCRIPTION: absurdityDescriptions[state.absurdity]
    };

    variables = addInterviewResponsesToVariables(variables, state);

    const systemPrompt = replaceVariables(promptTemplate.system, variables);
    const userPrompt = replaceVariables(promptTemplate.user, variables);

    const response = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ],
      max_completion_tokens: 500
    });

    const narrative = response.choices[0].message.content || "The cosmos remains mysteriously silent.";
    const executionTime = Date.now() - startTime;

    await logLlmCall(
      'generateNarrative',
      `SYSTEM:\n${systemPrompt}\n\nUSER:\n${userPrompt}`,
      narrative,
      { model: 'gpt-4o-mini', variables, checks },
      executionTime,
      state.id,
      state.turnNumber
    );

    return narrative;
  } catch (error) {
    console.error("Error generating narrative:", error);
    const executionTime = Date.now() - startTime;
    const errorMessage = "The narrative generator experienced a brief cosmic hiccup. Reality resumes shortly.";

    await logLlmCall(
      'generateNarrative',
      `Error: ${error}`,
      errorMessage,
      { error: String(error) },
      executionTime,
      state.id,
      state.turnNumber
    );

    return errorMessage;
  }
}

export async function generateActions(state: GameState): Promise<ActionChip[]> {
  const startTime = Date.now();

  try {
    const triggeredEvents = state.eventHistory.slice(-1)[0] || 'routine space operations';

    const criticalStats = [];
    if (state.stats.hull < 40) criticalStats.push('hull is low');
    if (state.stats.oxygen < 40) criticalStats.push('oxygen is low');
    if (state.stats.fuel < 40) criticalStats.push('fuel is low');
    if (state.stats.food < 40) criticalStats.push('food is low');
    if (state.stats.morale < 40) criticalStats.push('morale is low');
    if (state.stats.weirdness >= 4) criticalStats.push('weirdness is critical');

    const equippedItems = state.equippedItems
      .map(id => getItemById(id))
      .filter(Boolean);

    const equippedItemsDetail = equippedItems
      .map(i => `- ${i!.name} (${i!.icon}): ${i!.description}`)
      .join('\n') || '- None';

    const currentNarrative = state.turns[state.turns.length - 1]?.narrative || 'The journey to Uranus begins.';

    const promptTemplate = getPromptFromCache('action_generation');

    let variables: Record<string, any> = {
      DAY: state.day,
      TURN_NUMBER: state.turnNumber,
      SEGMENT: state.segment,
      RECENT_EVENT: triggeredEvents,
      CRITICAL_STATS: criticalStats.join(', ') || 'None',
      CURRENT_NARRATIVE: currentNarrative,
      EQUIPPED_ITEMS_DETAIL: equippedItemsDetail,
      ABSURDITY_DESCRIPTION: absurdityDescriptions[state.absurdity]
    };

    variables = addInterviewResponsesToVariables(variables, state);

    const systemPrompt = replaceVariables(promptTemplate.system, variables);
    const userPrompt = replaceVariables(promptTemplate.user, variables);

    const response = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ],
      response_format: { type: "json_object" },
      max_completion_tokens: 1000
    });

    const content = response.choices[0].message.content || "[]";
    const executionTime = Date.now() - startTime;

    let actions: ActionChip[];
    try {
      const parsed = JSON.parse(content);
      actions = Array.isArray(parsed) ? parsed : (parsed.actions || []);
    } catch {
      actions = [];
    }

    const validActions = actions.filter(a => 
      a.action && a.summary && a.risk && a.intent
    ).slice(0, 6);

    while (validActions.length < 6) {
      validActions.push({
        action: "Assess the situation carefully",
        summary: "Sometimes patience is the best strategy.",
        risk: "Safe",
        intent: "other"
      });
    }

    await logLlmCall(
      'generateActions',
      `SYSTEM:\n${systemPrompt}\n\nUSER:\n${userPrompt}`,
      content,
      { model: 'gpt-4o-mini', variables, actionCount: validActions.length },
      executionTime,
      state.id,
      state.turnNumber
    );

    return validActions;
  } catch (error) {
    console.error("Error generating actions:", error);
    const executionTime = Date.now() - startTime;

    const fallbackActions: ActionChip[] = [
      { action: "File paperwork about the issue", summary: "Bureaucracy solves everything. Eventually.", risk: "Safe" as const, intent: "command" as const },
      { action: "Improvise a solution", summary: "Wing it. What could go wrong?", risk: "Risky" as const, intent: "improvise" as const },
      { action: "Do something completely unexpected", summary: "Embrace the chaos.", risk: "Wild" as const, intent: "other" as const },
      { action: "Ask the crew for advice", summary: "Delegate the responsibility.", risk: "Safe" as const, intent: "negotiate" as const },
      { action: "Check the manual", summary: "There's always a manual. Probably.", risk: "Safe" as const, intent: "research" as const },
      { action: "Press random buttons", summary: "Science is basically trial and error.", risk: "Wild" as const, intent: "other" as const }
    ];

    await logLlmCall(
      'generateActions',
      `Error: ${error}`,
      JSON.stringify(fallbackActions),
      { error: String(error), fallback: true },
      executionTime,
      state.id,
      state.turnNumber
    );

    return fallbackActions;
  }
}

export async function mapCustomActionToIntent(customText: string): Promise<string> {
  const startTime = Date.now();

  try {
    const promptTemplate = getPromptFromCache('intent_mapping');

    const variables = {
      CUSTOM_ACTION: customText
    };

    const systemPrompt = replaceVariables(promptTemplate.system, variables);
    const userPrompt = replaceVariables(promptTemplate.user, variables);

    const response = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ],
      max_completion_tokens: 10
    });

    const intent = response.choices[0].message.content?.trim().toLowerCase() || "other";
    const executionTime = Date.now() - startTime;

    const validIntents = ['repair', 'negotiate', 'cook', 'explore', 'improvise', 'research', 'command', 'other'];
    const finalIntent = validIntents.includes(intent) ? intent : "other";

    await logLlmCall(
      'mapCustomActionToIntent',
      `SYSTEM:\n${systemPrompt}\n\nUSER:\n${userPrompt}`,
      intent,
      { model: 'gpt-4o-mini', variables, finalIntent },
      executionTime
    );

    return finalIntent;
  } catch (error) {
    console.error("Error mapping intent:", error);
    const executionTime = Date.now() - startTime;

    await logLlmCall(
      'mapCustomActionToIntent',
      `Error: ${error}`,
      'other',
      { error: String(error), fallback: true },
      executionTime
    );

    return "other";
  }
}

export async function generateImage(
  templateName: string, 
  gameState: GameState
): Promise<{ imageUrl: string; promptUsed: string } | null> {
  const startTime = Date.now();

  try {
    const template = getImagePromptByName(templateName);
    if (!template) {
      throw new Error(`Image prompt template "${templateName}" not found`);
    }

    const backgroundSetting = getPromptFromCache('image_background_setting');
    const backgroundValue = backgroundSetting.user || 'auto';

    const moderationSetting = getPromptFromCache('image_moderation_setting');
    const moderationValue = moderationSetting.user || 'auto';

    const equippedItems = gameState.equippedItems
      .map(id => getItemById(id))
      .filter((item): item is NonNullable<typeof item> => item !== undefined)
      .map(i => `${i.name} (${i.icon})`);

    const npcSummary = gameState.npcs.map(npc => 
      `${npc.name} (${npc.role})`
    ).join(', ');

    const currentNarrative = gameState.turns.length > 0 
      ? gameState.turns[gameState.turns.length - 1].narrative 
      : "The ship drifts through deep space.";

    const variables = {
      CURRENT_NARRATIVE: currentNarrative,
      SEGMENT: gameState.segment,
      DAY: gameState.day,
      HULL: gameState.stats.hull,
      OXYGEN: gameState.stats.oxygen,
      FUEL: gameState.stats.fuel,
      FOOD: gameState.stats.food,
      MORALE: gameState.stats.morale,
      EQUIPPED_ITEMS: equippedItems.join(', ') || 'None',
      NPC_SUMMARY: npcSummary,
      ABSURDITY_DESCRIPTION: absurdityDescriptions[gameState.absurdity]
    };

    const finalPrompt = replaceVariables(template.compiledTemplate, variables);

    // Generate cache keys and fingerprint
    const promptHash = generatePromptHash(finalPrompt);
    const variablesHash = generateVariablesHash(variables);
    const settings: ImageSettings = {
      size: template.size,
      quality: template.quality,
      background: backgroundValue,
      moderation: moderationValue
    };

    const sceneFingerprint = generateSceneFingerprint(
      templateName,
      gameState,
      variables,
      settings,
      Array.isArray(template.sceneTypes) ? template.sceneTypes : [],
      Array.isArray(template.tags) ? template.tags : []
    );

    // Check for exact cache match first
    let cachedImage = await storage.getGeneratedImageByHash(promptHash, variablesHash);
    let cacheStrategy = 'none';
    let similarityScore = 0;

    if (cachedImage) {
      // Exact match found
      await storage.updateImageAccess(cachedImage.id);
      const imageUrl = await loadImageFromFile(cachedImage.filePath);

      const executionTime = Date.now() - startTime;
      await logLlmCall(
        'generateImage',
        finalPrompt,
        imageUrl.substring(0, 100) + '... [cached]',
        { 
          model: 'gpt-image-1-mini', 
          templateName,
          variables,
          size: template.size,
          quality: template.quality,
          background: backgroundValue,
          moderation: moderationValue,
          cacheHit: true,
          cacheStrategy: 'exact',
          similarityScore: 1.0,
          cachedImageId: cachedImage.id
        },
        executionTime,
        gameState.id,
        gameState.turnNumber
      );

      return {
        imageUrl,
        promptUsed: finalPrompt
      };
    }

    // Check for similar scenes if no exact match
    const templateImages = await storage.getGeneratedImagesByTemplate(templateName);
    if (templateImages.length > 0) {
      const candidateFingerprints = templateImages.map(img => img.sceneFingerprint as SceneFingerprint);
      const similarScenes = findSimilarScenes(sceneFingerprint, candidateFingerprints, 0.85);

      if (similarScenes.length > 0) {
        const bestMatch = similarScenes[0];
        const bestMatchImage = templateImages.find(img => 
          JSON.stringify(img.sceneFingerprint) === JSON.stringify(bestMatch.fingerprint)
        );

        if (bestMatchImage) {
          await storage.updateImageAccess(bestMatchImage.id);
          const imageUrl = await loadImageFromFile(bestMatchImage.filePath);

          const executionTime = Date.now() - startTime;
          await logLlmCall(
            'generateImage',
            finalPrompt,
            imageUrl.substring(0, 100) + '... [similar]',
            { 
              model: 'gpt-image-1-mini', 
              templateName,
              variables,
              size: template.size,
              quality: template.quality,
              background: backgroundValue,
              moderation: moderationValue,
              cacheHit: true,
              cacheStrategy: 'similar',
              similarityScore: bestMatch.similarity.overallSimilarity,
              cachedImageId: bestMatchImage.id
            },
            executionTime,
            gameState.id,
            gameState.turnNumber
          );

          return {
            imageUrl,
            promptUsed: finalPrompt
          };
        }
      }
    }

    // No cache hit - generate new image
    const response = await openaiImages.images.generate({
      model: "gpt-image-1-mini",
      prompt: finalPrompt,
      n: 1,
      size: template.size as "1024x1024" | "1536x1024" | "1024x1536",
      quality: template.quality as "low" | "medium" | "high" | "auto",
      background: backgroundValue as "auto" | "transparent" | "opaque",
      moderation: moderationValue as "auto" | "low"
    });

    if (!response.data || response.data.length === 0) {
      throw new Error("No image data returned from OpenAI");
    }

    const imageData = response.data[0];
    const imageUrl = imageData.b64_json ? `data:image/png;base64,${imageData.b64_json}` : (imageData.url || "");

    // Save to cache
    try {
      const { filePath, fileSize } = await saveImageToFile(imageUrl, {
        templateName,
        promptHash,
        variablesHash,
        gameId: gameState.id,
        turnNumber: gameState.turnNumber,
        generatedAt: new Date()
      });

      await storage.createGeneratedImage({
        templateName,
        promptHash,
        variablesHash,
        filePath,
        fileSize,
        mimeType: 'image/png',
        sceneFingerprint,
        metadata: {
          variables,
          settings,
          promptUsed: finalPrompt,
          model: 'gpt-image-1-mini'
        },
        gameId: gameState.id,
        turnNumber: gameState.turnNumber
      });
    } catch (cacheError) {
      console.warn('Failed to cache generated image:', cacheError);
    }

    const executionTime = Date.now() - startTime;

    await logLlmCall(
      'generateImage',
      finalPrompt,
      imageUrl.substring(0, 100) + '... [generated]',
      { 
        model: 'gpt-image-1-mini', 
        templateName,
        variables,
        size: template.size,
        quality: template.quality,
        background: backgroundValue,
        moderation: moderationValue,
        cacheHit: false,
        cacheStrategy: 'none',
        similarityScore: 0
      },
      executionTime,
      gameState.id,
      gameState.turnNumber
    );

    return {
      imageUrl,
      promptUsed: finalPrompt
    };
  } catch (error) {
    console.error("Error generating image:", error);
    const executionTime = Date.now() - startTime;

    await logLlmCall(
      'generateImage',
      `Template: ${templateName}`,
      'Error',
      { error: String(error), fallback: true },
      executionTime,
      gameState.id,
      gameState.turnNumber
    );

    return null;
  }
}

