  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

interface PromptTemplate {
  id: string;
  name: string;
  content: string;
  systemContent: string | null;
  inheritGlobalPrompt: number;
  description: string | null;
  version: number;
  active: number;
  createdAt: string;
  updatedAt: string;
}

interface LlmLog {
  id: string;
  functionName: string;
  prompt: string;
  response: string;
  metadata: any;
  executionTimeMs: number | null;
  gameId: string | null;
  turnNumber: number | null;
  createdAt: string;
}

interface Event {
  id: string;
  name: string;
  segment: string;
  skill: string;
  dc: number;
  triggerCondition: string;
  passEffect: string;
  failEffect: string;
  tags: string | null;
  active: number;
  createdAt: string;
  updatedAt: string;
}

interface Item {
  id: string;
  name: string;
  description: string;
  icon: string;
  skillBonus: any | null;
  sceneEffect: any | null;
  tags: string | null;
  active: number;
  createdAt: string;
  updatedAt: string;
}

interface NpcTemplate {
  id: string;
  name: string;
  role: string;
  personality: string;
  quirk: string;
  icon: string;
  tags: string | null;
  active: number;
  createdAt: string;
  updatedAt: string;
}

interface ImagePrompt {
  id: string;
  name: string;
  promptTemplate: string;
  inheritVisualStyle: number;
  size: string;
  quality: string;
  description: string | null;
  sceneTypes: string | null;
  tags: string | null;
  active: number;
  createdAt: string;
  updatedAt: string;
}

export default function DevToolsPage() {
  const { toast } = useToast();
  const [selectedPrompt, setSelectedPrompt] = useState<PromptTemplate | null>(null);
  const [editedContent, setEditedContent] = useState("");
  const [editedSystemContent, setEditedSystemContent] = useState<string | null>(null);
  const [inheritGlobalPrompt, setInheritGlobalPrompt] = useState(1);
  const [logFilter, setLogFilter] = useState("");
  const [copiedItems, setCopiedItems] = useState<Set<string>>(new Set());

  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [isCreatingEvent, setIsCreatingEvent] = useState(false);
  const [eventForm, setEventForm] = useState({
    name: "",
    segment: "Departure",
    skill: "Engineering",
    dc: 12,
    triggerCondition: "{}",
    passEffect: "",
    failEffect: "",
    tags: "",
    active: 1
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [isCreatingItem, setIsCreatingItem] = useState(false);
  const [itemForm, setItemForm] = useState({
    name: "",
    description: "",
    icon: "",
    skillBonus: "{}",
    sceneEffect: "{}",
    tags: "",
    active: 1
  });

  const [selectedNpc, setSelectedNpc] = useState<NpcTemplate | null>(null);
  const [isCreatingNpc, setIsCreatingNpc] = useState(false);
  const [npcForm, setNpcForm] = useState({
    name: "",
    role: "",
    personality: "",
    quirk: "",
    icon: "",
    tags: "",
    active: 1
  });

  const [selectedImagePrompt, setSelectedImagePrompt] = useState<ImagePrompt | null>(null);
  const [isCreatingImagePrompt, setIsCreatingImagePrompt] = useState(false);
  const [imagePromptForm, setImagePromptForm] = useState({
    name: "",
    promptTemplate: "",
    inheritVisualStyle: 1,
    size: "1024x1024",
    quality: "auto",
    description: "",
    sceneTypes: "",
    tags: "",
    active: 1
  });

  const [visualStyleContent, setVisualStyleContent] = useState("");
  const [imageBackgroundSetting, setImageBackgroundSetting] = useState("auto");
  const [imageModerationSetting, setImageModerationSetting] = useState("auto");

  const [testImagePrompt, setTestImagePrompt] = useState<ImagePrompt | null>(null);
  const [showTestModal, setShowTestModal] = useState(false);

  const { data: prompts, isLoading: promptsLoading } = useQuery<PromptTemplate[]>({
    queryKey: ["/api/prompts"],
  });

  const { data: logs, isLoading: logsLoading } = useQuery<LlmLog[]>({
    queryKey: ["/api/llm-logs"],
  });

  const { data: events, isLoading: eventsLoading } = useQuery<Event[]>({
    queryKey: ["/api/events"],
  });

  const { data: items, isLoading: itemsLoading } = useQuery<Item[]>({
    queryKey: ["/api/items"],
  });

  const { data: npcs, isLoading: npcsLoading } = useQuery<NpcTemplate[]>({
    queryKey: ["/api/npc-templates"],
  });

  const { data: imagePrompts, isLoading: imagePromptsLoading } = useQuery<ImagePrompt[]>({
    queryKey: ["/api/image-prompts"],
  });

  useEffect(() => {
    if (prompts) {
      const visualStylePrompt = prompts.find(p => p.name === 'visual_style_prompt');
      if (visualStylePrompt) {
        setVisualStyleContent(visualStylePrompt.content);
      }

      const backgroundPrompt = prompts.find(p => p.name === 'image_background_setting');
      if (backgroundPrompt) {
        setImageBackgroundSetting(backgroundPrompt.content);
      }

      const moderationPrompt = prompts.find(p => p.name === 'image_moderation_setting');
      if (moderationPrompt) {
        setImageModerationSetting(moderationPrompt.content);
      }
    }
  }, [prompts]);

  const updatePromptMutation = useMutation({
    mutationFn: async ({ id, content, systemContent, inheritGlobalPrompt }: { 
      id: string; 
      content: string; 
      systemContent: string | null;
      inheritGlobalPrompt: number;
    }) => {
      return await apiRequest("PUT", `/api/prompts/${id}`, { content, systemContent, inheritGlobalPrompt });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/prompts"] });
      toast({
        title: "Prompt Updated",
        description: "The prompt template has been saved successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update Failed",
        description: "Failed to update the prompt template.",
        variant: "destructive",
      });
    },
  });

  const clearLogsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("DELETE", "/api/llm-logs");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/llm-logs"] });
      toast({
        title: "Logs Cleared",
        description: "All LLM logs have been deleted successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Clear Failed",
        description: "Failed to clear the logs.",
        variant: "destructive",
      });
    },
  });

  const syncPromptsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", "/api/prompts/sync");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/prompts"] });
      toast({
        title: "Prompts Synchronized",
        description: "Prompts have been updated from the database and cached.",
      });
    },
    onError: () => {
      toast({
        title: "Sync Failed",
        description: "Failed to synchronize prompts from database.",
        variant: "destructive",
      });
    },
  });

  const createEventMutation = useMutation({
    mutationFn: async (eventData: typeof eventForm) => {
      return await apiRequest("POST", "/api/events", eventData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/events"] });
      setIsCreatingEvent(false);
      setEventForm({
        name: "",
        segment: "Departure",
        skill: "Engineering",
        dc: 12,
        triggerCondition: "{}",
        passEffect: "",
        failEffect: "",
        tags: "",
        active: 1
      });
      toast({
        title: "Event Created",
        description: "The event has been created successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Creation Failed",
        description: "Failed to create the event.",
        variant: "destructive",
      });
    },
  });

  const updateEventMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: string } & Partial<typeof eventForm>) => {
      return await apiRequest("PUT", `/api/events/${id}`, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/events"] });
      toast({
        title: "Event Updated",
        description: "The event has been updated successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update Failed",
        description: "Failed to update the event.",
        variant: "destructive",
      });
    },
  });

  const reloadEventsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", "/api/events/reload");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/events"] });
      toast({
        title: "Events Reloaded",
        description: "Events have been reloaded from database into memory.",
      });
    },
    onError: () => {
      toast({
        title: "Reload Failed",
        description: "Failed to reload events from database.",
        variant: "destructive",
      });
    },
  });

  const createItemMutation = useMutation({
    mutationFn: async (itemData: any) => {
      return await apiRequest("POST", "/api/items", itemData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/items"] });
      setIsCreatingItem(false);
      setSelectedItem(null);
      toast({
        title: "Item Created",
        description: "The item has been created successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Creation Failed",
        description: "Failed to create the item.",
        variant: "destructive",
      });
    },
  });

  const updateItemMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: string } & any) => {
      return await apiRequest("PUT", `/api/items/${id}`, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/items"] });
      toast({
        title: "Item Updated",
        description: "The item has been updated successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update Failed",
        description: "Failed to update the item.",
        variant: "destructive",
      });
    },
  });

  const reloadItemsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", "/api/items/reload");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/items"] });
      toast({
        title: "Items Reloaded",
        description: "Items have been reloaded from database into memory.",
      });
    },
    onError: () => {
      toast({
        title: "Reload Failed",
        description: "Failed to reload items from database.",
        variant: "destructive",
      });
    },
  });

  const createNpcMutation = useMutation({
    mutationFn: async (npcData: any) => {
      return await apiRequest("POST", "/api/npc-templates", npcData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/npc-templates"] });
      setIsCreatingNpc(false);
      setSelectedNpc(null);
      toast({
        title: "NPC Created",
        description: "The NPC template has been created successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Creation Failed",
        description: "Failed to create the NPC template.",
        variant: "destructive",
      });
    },
  });

  const updateNpcMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: string } & any) => {
      return await apiRequest("PUT", `/api/npc-templates/${id}`, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/npc-templates"] });
      toast({
        title: "NPC Updated",
        description: "The NPC template has been updated successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update Failed",
        description: "Failed to update the NPC template.",
        variant: "destructive",
      });
    },
  });

  const reloadNpcsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", "/api/npc-templates/reload");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/npc-templates"] });
      toast({
        title: "NPCs Reloaded",
        description: "NPC templates have been reloaded from database into memory.",
      });
    },
    onError: () => {
      toast({
        title: "Reload Failed",
        description: "Failed to reload NPC templates from database.",
        variant: "destructive",
      });
    },
  });

  const createImagePromptMutation = useMutation({
    mutationFn: async (imagePromptData: any) => {
      return await apiRequest("POST", "/api/image-prompts", imagePromptData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/image-prompts"] });
      setIsCreatingImagePrompt(false);
      setSelectedImagePrompt(null);
      toast({
        title: "Image Prompt Created",
        description: "The image prompt template has been created successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Creation Failed",
        description: "Failed to create the image prompt template.",
        variant: "destructive",
      });
    },
  });

  const updateImagePromptMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: string } & any) => {
      return await apiRequest("PUT", `/api/image-prompts/${id}`, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/image-prompts"] });
      toast({
        title: "Image Prompt Updated",
        description: "The image prompt template has been updated successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update Failed",
        description: "Failed to update the image prompt template.",
        variant: "destructive",
      });
    },
  });

  const reloadImagePromptsMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", "/api/image-prompts/reload");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/image-prompts"] });
      toast({
        title: "Image Prompts Reloaded",
        description: "Image prompt templates have been reloaded from database into memory.",
      });
    },
    onError: () => {
      toast({
        title: "Reload Failed",
        description: "Failed to reload image prompt templates from database.",
        variant: "destructive",
      });
    },
  });

  const handleSelectPrompt = (prompt: PromptTemplate) => {
    setSelectedPrompt(prompt);
    setEditedContent(prompt.content);
    setEditedSystemContent(prompt.systemContent || null);
    setInheritGlobalPrompt(prompt.inheritGlobalPrompt);
  };

  const handleSavePrompt = () => {
    if (selectedPrompt) {
      updatePromptMutation.mutate({
        id: selectedPrompt.id,
        content: editedContent,
        systemContent: editedSystemContent,
        inheritGlobalPrompt: inheritGlobalPrompt,
      });
    }
  };

  const handleSelectEvent = (event: Event) => {
    setSelectedEvent(event);
    setIsCreatingEvent(false);
    setEventForm({
      name: event.name,
      segment: event.segment,
      skill: event.skill,
      dc: event.dc,
      triggerCondition: typeof event.triggerCondition === 'string' 
        ? event.triggerCondition 
        : JSON.stringify(event.triggerCondition, null, 2),
      passEffect: event.passEffect,
      failEffect: event.failEffect,
      tags: event.tags || "",
      active: event.active
    });
  };

  const handleCreateNewEvent = () => {
    setSelectedEvent(null);
    setIsCreatingEvent(true);
    setEventForm({
      name: "",
      segment: "Departure",
      skill: "Engineering",
      dc: 12,
      triggerCondition: "{}",
      passEffect: "",
      failEffect: "",
      tags: "",
      active: 1
    });
  };

  const handleSaveEvent = () => {
    if (isCreatingEvent) {
      createEventMutation.mutate(eventForm);
    } else if (selectedEvent) {
      updateEventMutation.mutate({
        id: selectedEvent.id,
        ...eventForm
      });
    }
  };

  const handleSelectItem = (item: Item) => {
    setSelectedItem(item);
    setIsCreatingItem(false);
    setItemForm({
      name: item.name,
      description: item.description,
      icon: item.icon,
      skillBonus: typeof item.skillBonus === 'string' ? item.skillBonus : JSON.stringify(item.skillBonus || {}, null, 2),
      sceneEffect: typeof item.sceneEffect === 'string' ? item.sceneEffect : JSON.stringify(item.sceneEffect || {}, null, 2),
      tags: item.tags || "",
      active: item.active
    });
  };

  const handleCreateNewItem = () => {
    setSelectedItem(null);
    setIsCreatingItem(true);
    setItemForm({
      name: "",
      description: "",
      icon: "",
      skillBonus: "{}",
      sceneEffect: "{}",
      tags: "",
      active: 1
    });
  };

  const handleSaveItem = () => {
    const itemData = {
      ...itemForm,
      skillBonus: itemForm.skillBonus ? JSON.parse(itemForm.skillBonus) : null,
      sceneEffect: itemForm.sceneEffect ? JSON.parse(itemForm.sceneEffect) : null,
    };

    if (isCreatingItem) {
      createItemMutation.mutate(itemData);
    } else if (selectedItem) {
      updateItemMutation.mutate({
        id: selectedItem.id,
        ...itemData
      });
    }
  };

  const handleSelectNpc = (npc: NpcTemplate) => {
    setSelectedNpc(npc);
    setIsCreatingNpc(false);
    setNpcForm({
      name: npc.name,
      role: npc.role,
      personality: npc.personality,
      quirk: npc.quirk,
      icon: npc.icon,
      tags: npc.tags || "",
      active: npc.active
    });
  };

  const handleCreateNewNpc = () => {
    setSelectedNpc(null);
    setIsCreatingNpc(true);
    setNpcForm({
      name: "",
      role: "",
      personality: "",
      quirk: "",
      icon: "",
      tags: "",
      active: 1
    });
  };

  const handleSaveNpc = () => {
    if (isCreatingNpc) {
      createNpcMutation.mutate(npcForm);
    } else if (selectedNpc) {
      updateNpcMutation.mutate({
        id: selectedNpc.id,
        ...npcForm
      });
    }
  };

  const handleSelectImagePrompt = (imagePrompt: ImagePrompt) => {
    setSelectedImagePrompt(imagePrompt);
    setIsCreatingImagePrompt(false);
    setImagePromptForm({
      name: imagePrompt.name,
      promptTemplate: imagePrompt.promptTemplate,
      inheritVisualStyle: imagePrompt.inheritVisualStyle ?? 1,
      size: imagePrompt.size || "1024x1024",
      quality: imagePrompt.quality || "auto",
      description: imagePrompt.description || "",
      sceneTypes: imagePrompt.sceneTypes || "",
      tags: imagePrompt.tags || "",
      active: imagePrompt.active
    });
  };

  const handleCreateNewImagePrompt = () => {
    setSelectedImagePrompt(null);
    setIsCreatingImagePrompt(true);
    setImagePromptForm({
      name: "",
      promptTemplate: "",
      inheritVisualStyle: 1,
      size: "1024x1024",
      quality: "auto",
      description: "",
      sceneTypes: "",
      tags: "",
      active: 1
    });
  };

  const handleSaveImagePrompt = () => {
    if (isCreatingImagePrompt) {
      createImagePromptMutation.mutate(imagePromptForm);
    } else if (selectedImagePrompt) {
      updateImagePromptMutation.mutate({
        id: selectedImagePrompt.id,
        ...imagePromptForm
      });
    }
  };

  const handleSaveVisualStyle = () => {
    const visualStylePrompt = prompts?.find(p => p.name === 'visual_style_prompt');
    const backgroundPrompt = prompts?.find(p => p.name === 'image_background_setting');
    const moderationPrompt = prompts?.find(p => p.name === 'image_moderation_setting');

    if (visualStylePrompt) {
      updatePromptMutation.mutate({
        id: visualStylePrompt.id,
        content: visualStyleContent,
        systemContent: null,
        inheritGlobalPrompt: 0
      });
    }

    if (backgroundPrompt) {
      updatePromptMutation.mutate({
        id: backgroundPrompt.id,
        content: imageBackgroundSetting,
        systemContent: null,
        inheritGlobalPrompt: 0
      });
    }

    if (moderationPrompt) {
      updatePromptMutation.mutate({
        id: moderationPrompt.id,
        content: imageModerationSetting,
        systemContent: null,
        inheritGlobalPrompt: 0
      });
    }
  };

  const handleCopy = async (text: string, itemId: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedItems(prev => new Set(prev).add(itemId));
      toast({
        title: "Copied to clipboard",
        description: "The content has been copied successfully.",
      });

      setTimeout(() => {
        setCopiedItems(prev => {
          const next = new Set(prev);
          next.delete(itemId);
          return next;
        });
      }, 2000);
    } catch (error) {
      toast({
        title: "Copy failed",
        description: "Failed to copy to clipboard.",
        variant: "destructive",
      });
    }
  };

  const filteredLogs = logs?.filter(log => 
    log.functionName.toLowerCase().includes(logFilter.toLowerCase()) ||
    log.prompt.toLowerCase().includes(logFilter.toLowerCase()) ||
    log.response.toLowerCase().includes(logFilter.toLowerCase())
  ) || [];

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto p-4 max-w-7xl">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <Link href="/">
              <Button variant="ghost" size="icon" data-testid="button-back">
                <ArrowLeft className="h-5 w-5" />
              </Button>
            </Link>
            <div>
              <h1 className="text-3xl font-bold">Developer Tools</h1>
              <p className="text-muted-foreground">Manage prompts, events, and analyze LLM interactions</p>
            </div>
          </div>
        </div>

        <Tabs defaultValue="prompts" className="w-full">
          <TabsList className="grid w-full grid-cols-8 max-w-6xl" data-testid="tabs-devtools">
            <TabsTrigger value="prompts" data-testid="tab-prompts">Prompts</TabsTrigger>
            <TabsTrigger value="events" data-testid="tab-events">Events</TabsTrigger>
            <TabsTrigger value="items" data-testid="tab-items">Items</TabsTrigger>
            <TabsTrigger value="npcs" data-testid="tab-npcs">NPCs</TabsTrigger>
            <TabsTrigger value="image-prompts" data-testid="tab-image-prompts">Image Prompts</TabsTrigger>
            <TabsTrigger value="interview" data-testid="tab-interview">Interview</TabsTrigger>
            <TabsTrigger value="logs" data-testid="tab-logs">LLM Logs</TabsTrigger>
            <TabsTrigger value="cache" data-testid="tab-cache">Image Cache</TabsTrigger>
          </TabsList>

          <TabsContent value="prompts" className="space-y-4">
            <div className="grid md:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle>Prompt Templates</CardTitle>
                      <CardDescription>
                        Select a prompt template to edit
                      </CardDescription>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => syncPromptsMutation.mutate()}
                      disabled={syncPromptsMutation.isPending}
                      data-testid="button-sync-prompts"
                    >
                      <RefreshCw className={`h-4 w-4 mr-2 ${syncPromptsMutation.isPending ? 'animate-spin' : ''}`} />
                      {syncPromptsMutation.isPending ? "Syncing..." : "Update Prompts"}
                    </Button>
                  </div>
                </CardHeader>
                <CardContent>
                  <ScrollArea className="h-[600px]">
                    {promptsLoading ? (
                      <p className="text-muted-foreground">Loading prompts...</p>
                    ) : (
                      <div className="space-y-2">
                        {prompts?.filter(p => 
                          p.name !== 'visual_style_prompt' && 
                          p.name !== 'image_background_setting' && 
                          p.name !== 'image_moderation_setting'
                        ).map((prompt) => (
                          <Button
                            key={prompt.id}
                            variant={selectedPrompt?.id === prompt.id ? "secondary" : "ghost"}
                            className="w-full justify-start"
                            onClick={() => handleSelectPrompt(prompt)}
                            data-testid={`button-prompt-${prompt.name}`}
                          >
                            <div className="flex flex-col items-start w-full">
