                                      <Check className="h-3 w-3" />
                                    ) : (
                                      <Copy className="h-3 w-3" />
                                    )}
                                  </Button>
                                </div>
                                <div className="mt-1 p-3 bg-muted rounded-md text-xs font-mono whitespace-pre-wrap max-h-40 overflow-auto">
                                  {log.prompt}
                                </div>
                              </div>
                              <div>
                                <div className="flex items-center justify-between mb-1">
                                  <Label className="text-xs font-semibold">Response</Label>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    onClick={() => handleCopy(log.response, `${log.id}-response`)}
                                    data-testid={`button-copy-response-${log.id}`}
                                    className="h-6 w-6"
                                  >
                                    {copiedItems.has(`${log.id}-response`) ? (
                                      <Check className="h-3 w-3" />
                                    ) : (
                                      <Copy className="h-3 w-3" />
                                    )}
                                  </Button>
                                </div>
                                <div className="mt-1 p-3 bg-muted rounded-md text-xs font-mono whitespace-pre-wrap max-h-40 overflow-auto">
                                  {log.response}
                                </div>
                              </div>
                              {log.metadata && Object.keys(log.metadata).length > 0 && (
                                <div>
                                  <Label className="text-xs font-semibold">Metadata</Label>
                                  <div className="mt-1 p-3 bg-muted rounded-md text-xs font-mono">
                                    {JSON.stringify(log.metadata, null, 2)}
                                  </div>
                                </div>
                              )}
                            </CardContent>
                          </Card>
                        ))}
                        {filteredLogs.length === 0 && (
                          <div className="text-center text-muted-foreground py-8">
                            No logs found matching your filter
                          </div>
                        )}
                      </div>
                    )}
                  </ScrollArea>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="cache" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Image Cache Management</CardTitle>
                <CardDescription>
                  Manage cached generated images and view cache analytics
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-between">
                  <p className="text-sm text-muted-foreground">
                    Access the full cache management interface to view, manage, and analyze your cached images.
                  </p>
                  <Link to="/dev-tools/cache">
                    <Button>
                      <ImageIcon className="h-4 w-4 mr-2" />
                      Open Cache Manager
                    </Button>
                  </Link>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>

      {testImagePrompt && (
        <ImageTestModal
          open={showTestModal}
          onOpenChange={setShowTestModal}
          templateName={testImagePrompt.name}
          promptTemplate={testImagePrompt.promptTemplate}
          inheritVisualStyle={testImagePrompt.inheritVisualStyle === 1}
        />
      )}
    </div>
  );
}

