import { describe, it, expect } from 'vitest';
import OpenAI from 'openai';

// Integration test - actually calls GPT-4o-mini to verify connectivity
describe('OpenAI Integration Test', () => {
  it('should successfully connect to GPT-4o-mini through Replit AI Integrations', async () => {
    const openai = new OpenAI({
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY
    });

    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        { role: 'user', content: 'Say "hello" in exactly one word.' }
      ],
      max_completion_tokens: 10
    });

    expect(response).toBeDefined();
    expect(response.choices).toBeDefined();
    expect(response.choices.length).toBeGreaterThan(0);
    expect(response.choices[0].message.content).toBeDefined();
    expect(typeof response.choices[0].message.content).toBe('string');

    // Should contain some variation of "hello"
    const content = response.choices[0].message.content?.toLowerCase() || '';
    expect(content.length).toBeGreaterThan(0);
  }, 30000); // 30 second timeout for API call
});

