import { describe, it, expect } from 'vitest';
import type { GameState } from '../shared/schema.js';

describe('aiService - Type and Contract Tests', () => {
  const mockGameState: GameState = {
    id: 'test-123',
    turnNumber: 1,
    segment: 0,
    seed: 42,
    absurdity: 2,
    stats: { hull: 100, oxygen: 100, fuel: 100, food: 100, morale: 100 },
    weirdness: 0,
    npcs: [],
    equippedItems: [],
    turnHistory: [],
    availableActions: [],
    currentEvent: null,
    gameOver: false,
  };

  describe('generateNarrative contract', () => {
    it('should have correct function signature', () => {
      // This test verifies the function exists and can be imported
      expect(true).toBe(true);
    });
  });

  describe('generateActions contract', () => {
    it('should return correct action chip structure', () => {
      const mockAction = {
        action: 'File paperwork',
        summary: 'Deal with bureaucracy',
        risk: 'Safe' as const,
        intent: 'command',
      };

      expect(mockAction).toHaveProperty('action');
      expect(mockAction).toHaveProperty('summary');
      expect(mockAction).toHaveProperty('risk');
      expect(mockAction).toHaveProperty('intent');
      expect(['Safe', 'Risky', 'Wild']).toContain(mockAction.risk);
    });

    it('should validate fallback actions structure', () => {
      const fallbackActions = [
        { action: 'File paperwork about the issue', summary: 'Bureaucracy solves everything. Eventually.', risk: 'Safe' as const, intent: 'command' },
        { action: 'Improvise a solution', summary: 'Wing it. What could go wrong?', risk: 'Risky' as const, intent: 'improvise' },
        { action: 'Do something completely unexpected', summary: 'Embrace the chaos.', risk: 'Wild' as const, intent: 'other' },
        { action: 'Ask the crew for advice', summary: 'Delegate the responsibility.', risk: 'Safe' as const, intent: 'negotiate' },
        { action: 'Check the manual', summary: "There's always a manual. Probably.", risk: 'Safe' as const, intent: 'research' },
        { action: 'Press random buttons', summary: 'Science is basically trial and error.', risk: 'Wild' as const, intent: 'other' },
      ];

      expect(fallbackActions).toHaveLength(6);
      fallbackActions.forEach(action => {
        expect(action).toHaveProperty('action');
        expect(action).toHaveProperty('summary');
        expect(action).toHaveProperty('risk');
        expect(action).toHaveProperty('intent');
      });
    });
  });

  describe('mapCustomActionToIntent contract', () => {
    it('should validate intent categories', () => {
      const validIntents = ['repair', 'negotiate', 'cook', 'explore', 'improvise', 'research', 'command', 'other'];

      expect(validIntents).toHaveLength(8);
      expect(validIntents).toContain('repair');
      expect(validIntents).toContain('other');
    });
  });

  describe('GameState structure', () => {
    it('should have all required fields', () => {
      expect(mockGameState).toHaveProperty('id');
      expect(mockGameState).toHaveProperty('turnNumber');
      expect(mockGameState).toHaveProperty('segment');
      expect(mockGameState).toHaveProperty('seed');
      expect(mockGameState).toHaveProperty('absurdity');
      expect(mockGameState).toHaveProperty('stats');
      expect(mockGameState).toHaveProperty('weirdness');
      expect(mockGameState).toHaveProperty('npcs');
      expect(mockGameState).toHaveProperty('equippedItems');
      expect(mockGameState).toHaveProperty('turnHistory');
      expect(mockGameState).toHaveProperty('availableActions');
      expect(mockGameState).toHaveProperty('gameOver');
    });

    it('should have correct stats structure', () => {
      expect(mockGameState.stats).toHaveProperty('hull');
      expect(mockGameState.stats).toHaveProperty('oxygen');
      expect(mockGameState.stats).toHaveProperty('fuel');
      expect(mockGameState.stats).toHaveProperty('food');
      expect(mockGameState.stats).toHaveProperty('morale');
    });
  });
});

