import { writeFile, readFile } from "fs/promises";
import { existsSync } from "fs";
import path from "path";
import { storage } from "./storage.js";

const PROMPTS_FILE = path.join(process.cwd(), "server", "prompts.json");

export interface ComputedPrompt {
  system: string;
  user: string;
}

const promptCache = new Map<string, ComputedPrompt>();

export async function exportPromptsToJSON(): Promise<void> {
  console.log("Exporting prompts from database to JSON...");

  const prompts = await storage.getAllPromptTemplates();

  if (prompts.length === 0) {
    throw new Error("No prompts found in database. Cannot export to JSON.");
  }

  // Find the global system prompt
  const globalPrompt = prompts.find(p => p.name === 'global_system_prompt');
  if (!globalPrompt) {
    throw new Error("global_system_prompt not found in database. Cannot compute prompts.");
  }

  const computedPrompts: Record<string, ComputedPrompt> = {};

  for (const prompt of prompts) {
    let systemPrompt: string;

    if (prompt.name === 'global_system_prompt') {
      // The global prompt itself - just use its content as system
      systemPrompt = prompt.content;
    } else {
      // Scenario-specific prompt - apply inheritance logic
      if (prompt.inheritGlobalPrompt === 1) {
        // Inherit: global + scenario extension
        systemPrompt = globalPrompt.content;
        if (prompt.systemContent) {
          systemPrompt = systemPrompt + "\n\n" + prompt.systemContent;
        }
      } else {
        // Override: use only scenario's system content
        systemPrompt = prompt.systemContent || "";
      }
    }

    computedPrompts[prompt.name] = {
      system: systemPrompt,
      user: prompt.content
    };
  }

  await writeFile(PROMPTS_FILE, JSON.stringify(computedPrompts, null, 2), "utf-8");
  console.log(`✅ Exported ${prompts.length} prompts to ${PROMPTS_FILE}`);
}

export async function loadPromptsIntoMemory(): Promise<void> {
  console.log("Loading prompts from JSON into memory...");

  if (!existsSync(PROMPTS_FILE)) {
    throw new Error(`Prompts file not found at ${PROMPTS_FILE}. Run exportPromptsToJSON() first.`);
  }

  const fileContent = await readFile(PROMPTS_FILE, "utf-8");

  let promptsObject: Record<string, ComputedPrompt>;
  try {
    promptsObject = JSON.parse(fileContent);
  } catch (error) {
    throw new Error(`Failed to parse prompts.json: ${error}`);
  }

  promptCache.clear();

  let count = 0;
  for (const [name, prompt] of Object.entries(promptsObject)) {
    promptCache.set(name, prompt);
    count++;
  }

  console.log(`✅ Loaded ${count} prompts into memory cache`);
}

export function getPromptFromCache(name: string): ComputedPrompt {
  const prompt = promptCache.get(name);

  if (!prompt) {
    throw new Error(`Prompt '${name}' not found in cache. Available prompts: ${Array.from(promptCache.keys()).join(", ")}`);
  }

  return prompt;
}

export async function syncPromptsFromDatabase(): Promise<void> {
  await exportPromptsToJSON();
  await loadPromptsIntoMemory();
  console.log("✅ Prompts synchronized from database");
}

export function getCacheStats(): { size: number; prompts: string[] } {
  return {
    size: promptCache.size,
    prompts: Array.from(promptCache.keys())
  };
}

