import { storage } from "./storage.js";
import type { EventDefinition, TriggerCondition, GameState } from "@shared/schema";

let eventCache: EventDefinition[] = [];

// Convert JSON trigger condition to evaluatable function
function compileTriggerCondition(condition: TriggerCondition): (state: GameState) => boolean {
  switch (condition.type) {
    case 'stat': {
      return (state: GameState) => {
        const statValue = state.stats[condition.stat];
        switch (condition.operator) {
          case '>=': return statValue >= condition.value;
          case '<=': return statValue <= condition.value;
          case '>': return statValue > condition.value;
          case '<': return statValue < condition.value;
          case '==': return statValue === condition.value;
          default: return false;
        }
      };
    }
    case 'day_modulo': {
      return (state: GameState) => state.day % condition.divisor === condition.remainder;
    }
    case 'random': {
      return () => Math.random() < condition.chance;
    }
    case 'or': {
      const compiledConditions = condition.conditions.map(compileTriggerCondition);
      return (state: GameState) => compiledConditions.some(fn => fn(state));
    }
    case 'and': {
      const compiledConditions = condition.conditions.map(compileTriggerCondition);
      return (state: GameState) => compiledConditions.every(fn => fn(state));
    }
    default:
      return () => false;
  }
}

export async function loadEventsIntoMemory(): Promise<void> {
  console.log("Loading events from database into memory...");

  const dbEvents = await storage.getActiveEvents();

  if (dbEvents.length === 0) {
    console.warn("⚠️  No active events found in database. Events will not trigger.");
    eventCache = [];
    return;
  }

  eventCache = dbEvents.map(event => ({
    id: event.id,
    name: event.name,
    segment: event.segment as any,
    tags: event.tags as string[],
    triggerCondition: event.triggerCondition as TriggerCondition,
    skill: event.skill as any,
    dc: event.dc,
    passEffect: event.passEffect,
    failEffect: event.failEffect,
    active: event.active === 1,
  }));

  console.log(`✅ Loaded ${eventCache.length} active events into memory cache`);
}

export function getActiveEvents(): EventDefinition[] {
  return eventCache;
}

export function evaluateTriggerCondition(event: EventDefinition, state: GameState): boolean {
  const evaluator = compileTriggerCondition(event.triggerCondition);
  return evaluator(state);
}

export function getCacheStats(): { count: number; events: string[] } {
  return {
    count: eventCache.length,
    events: eventCache.map(e => e.name)
  };
}

