import { storage } from "./storage.js";
import type { Item } from "@shared/schema";
import type { ItemRow } from "@shared/schema";

let itemCache: Item[] = [];

// Convert database row to runtime Item interface
function convertToItem(row: ItemRow): Item {
  return {
    id: row.id,
    name: row.name,
    description: row.description,
    icon: row.icon,
    skillBonus: row.skillBonusSkill && row.skillBonusValue 
      ? { skill: row.skillBonusSkill as any, bonus: row.skillBonusValue }
      : undefined,
    sceneEffect: row.sceneEffectTags && row.sceneEffectEffect
      ? { tags: row.sceneEffectTags as string[], effect: row.sceneEffectEffect }
      : undefined,
    efficiency: row.efficiency as Item['efficiency']
  };
}

export async function loadItemsIntoMemory(): Promise<void> {
  console.log("Loading items from database into memory...");

  const dbItems = await storage.getActiveItems();

  if (dbItems.length === 0) {
    console.warn("⚠️  No active items found in database. Item system will not function.");
    itemCache = [];
    return;
  }

  itemCache = dbItems.map(convertToItem);

  console.log(`✅ Loaded ${itemCache.length} active items into memory cache`);
}

export function getActiveItems(): Item[] {
  return itemCache;
}

export function getItemById(id: string): Item | undefined {
  return itemCache.find(item => item.id === id);
}

export function getCacheStats(): { count: number; items: string[] } {
  return {
    count: itemCache.length,
    items: itemCache.map(i => i.name)
  };
}

