import { storage } from "./storage.js";
import type { NPC, NpcTemplate } from "@shared/schema";

let npcTemplateCache: NpcTemplate[] = [];

// Convert NPC template to initial NPC state for new game
export function createNpcFromTemplate(template: NpcTemplate): NPC {
  return {
    id: template.id,
    name: template.name,
    role: template.role,
    affinity: template.startingAffinity,
    status: 'Indifferent',
  };
}

export async function loadNpcTemplatesIntoMemory(): Promise<void> {
  console.log("Loading NPC templates from database into memory...");

  const dbNpcs = await storage.getActiveNpcTemplates();

  if (dbNpcs.length === 0) {
    console.warn("⚠️  No active NPC templates found in database. Games will have no crew members.");
    npcTemplateCache = [];
    return;
  }

  npcTemplateCache = dbNpcs;

  console.log(`✅ Loaded ${npcTemplateCache.length} active NPC templates into memory cache`);
}

export function getActiveNpcTemplates(): NpcTemplate[] {
  return npcTemplateCache;
}

export function getNpcTemplateById(id: string): NpcTemplate | undefined {
  return npcTemplateCache.find(npc => npc.id === id);
}

export function getInitialNpcs(): NPC[] {
  return npcTemplateCache.map(createNpcFromTemplate);
}

export function getCacheStats(): { count: number; npcs: string[] } {
  return {
    count: npcTemplateCache.length,
    npcs: npcTemplateCache.map(n => n.name)
  };
}

