import { useState, useEffect, useRef } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { useLocation } from 'wouter';
import { queryClient, apiRequest } from '@/lib/queryClient';
import type { GameState, GameStats, ActionChip, Turn, NPC, ItemRow } from '@shared/schema';

type ViewMode = 'main' | 'stats' | 'crew' | 'items' | 'help';

interface TerminalGamePageProps {
  gameId: string;
  initialGameState: GameState;
}

export default function TerminalGamePage({ gameId, initialGameState }: TerminalGamePageProps) {
  const [, setLocation] = useLocation();
  const [commandHistory, setCommandHistory] = useState<string[]>([]);
  const [currentCommand, setCurrentCommand] = useState('');
  const [viewMode, setViewMode] = useState<ViewMode>('main');
  const [typewriterText, setTypewriterText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingComplete, setTypingComplete] = useState(false);
  const terminalRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Fetch game state
  const { data: gameState } = useQuery<GameState>({
    queryKey: [`/api/game/${gameId}`],
    enabled: !!gameId,
    initialData: initialGameState,
  });

  // Fetch items
  const { data: itemsData } = useQuery<ItemRow[]>({
    queryKey: ['/api/items'],
  });

  // Submit action mutation
  const submitActionMutation = useMutation({
    mutationFn: async (playerAction: string) => {
      const response = await apiRequest('POST', `/api/game/action`, { 
        gameId,
        action: playerAction 
      });
      return await response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/game/${gameId}`] });
      setCommandHistory((prev) => [...prev, `> Action submitted: Loading response...`]);
    },
  });

  // Typewriter effect for new narrative
  useEffect(() => {
    if (!gameState?.turns?.length || isTyping) return;

    const lastTurn = gameState.turns[gameState.turns.length - 1];
    if (!lastTurn?.narrative) return;

    const fullText = lastTurn.narrative;
    setIsTyping(true);
    setTypingComplete(false);
    setTypewriterText('');

    let index = 0;
    const interval = setInterval(() => {
      if (index < fullText.length) {
        setTypewriterText(fullText.substring(0, index + 1));
        index++;
      } else {
        setIsTyping(false);
        setTypingComplete(true);
        clearInterval(interval);
      }
    }, 20); // 20ms per character

    return () => clearInterval(interval);
  }, [gameState?.turns?.length]);

  // Auto-scroll terminal
  useEffect(() => {
    if (terminalRef.current) {
      terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
    }
  }, [commandHistory, typewriterText]);

  // Focus input on mount and click
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleTerminalClick = () => {
    inputRef.current?.focus();
  };

  // Parse and execute command
  const executeCommand = (cmd: string) => {
    const trimmed = cmd.trim().toLowerCase();
    setCommandHistory((prev) => [...prev, `> ${cmd}`]);
    setCurrentCommand('');

    // Empty command
    if (!trimmed) {
      setCommandHistory((prev) => [...prev, 'Type "help" for available commands.']);
      return;
    }

    // Help command
    if (trimmed === 'help' || trimmed === 'h' || trimmed === '?') {
      setViewMode('help');
      setCommandHistory((prev) => [
        ...prev,
        '=== AVAILABLE COMMANDS ===',
        'help, h, ?       - Show this help message',
        'stats, s         - View ship status and resources',
        'crew, c          - View crew roster and relationships',
        'items, i         - View inventory and equipped items',
        '1-5              - Select action by number',
        'back, clear, cls - Return to main view',
        'exit, quit       - Return to main menu',
        '=========================',
      ]);
      return;
    }

    // Stats command
    if (trimmed === 'stats' || trimmed === 's') {
      setViewMode('stats');
      return;
    }

    // Crew command
    if (trimmed === 'crew' || trimmed === 'c') {
      setViewMode('crew');
      return;
    }

    // Items command
    if (trimmed === 'items' || trimmed === 'i' || trimmed === 'inv' || trimmed === 'inventory') {
      setViewMode('items');
      return;
    }

    // Back/clear command
    if (trimmed === 'back' || trimmed === 'clear' || trimmed === 'cls') {
      setViewMode('main');
      setCommandHistory((prev) => [...prev, 'Returned to main view.']);
      return;
    }

    // Exit command
    if (trimmed === 'exit' || trimmed === 'quit') {
      localStorage.removeItem('currentGameId');
      setLocation('/');
      return;
    }

    // Action selection (1-5)
    const actionNum = parseInt(trimmed);
    if (actionNum >= 1 && actionNum <= 5 && gameState?.currentActions?.length) {
      const action = gameState.currentActions[actionNum - 1];
      if (action) {
        setCommandHistory((prev) => [...prev, `Executing action: ${action.summary}`]);
        submitActionMutation.mutate(action.action);
      } else {
        setCommandHistory((prev) => [...prev, `Error: Action ${actionNum} not available.`]);
      }
      return;
    }

    // Unknown command
    setCommandHistory((prev) => [...prev, `Unknown command: "${cmd}". Type "help" for available commands.`]);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      executeCommand(currentCommand);
    }
  };

  // Render different views
  const renderStats = () => {
    if (!gameState?.stats) return null;
    const stats: GameStats = gameState.stats;

    return (
      <div className="terminal-text font-mono">
        <div className="terminal-text-bright mb-2">╔══════════════════════════════╗</div>
        <div className="terminal-text-bright mb-2">║      SHIP STATUS             ║</div>
        <div className="terminal-text-bright mb-3">╚══════════════════════════════╝</div>

        <div className="mb-1">Hull Integrity:  [{createBar(stats.hull, 100)}] {stats.hull}%</div>
        <div className="mb-1">Oxygen Level:    [{createBar(stats.oxygen, 100)}] {stats.oxygen}%</div>
        <div className="mb-1">Fuel Reserves:   [{createBar(stats.fuel, 100)}] {stats.fuel}%</div>
        <div className="mb-1">Food Supplies:   [{createBar(stats.food, 100)}] {stats.food}%</div>
        <div className="mb-1">Crew Morale:     [{createBar(stats.morale, 100)}] {stats.morale}%</div>
        <div className="mt-2 terminal-text-bright">Weirdness Level: {'█'.repeat(stats.weirdness)}{'░'.repeat(5 - stats.weirdness)} ({stats.weirdness}/5)</div>

        <div className="mt-3 terminal-text-dim">Current Segment: {gameState.segment}</div>
        <div className="terminal-text-dim">Day: {gameState.day} | Turn: {gameState.turnNumber}</div>
      </div>
    );
  };

  const renderCrew = () => {
    if (!gameState?.npcs) return null;
    const npcs: NPC[] = gameState.npcs;

    return (
      <div className="terminal-text font-mono">
        <div className="terminal-text-bright mb-2">╔══════════════════════════════╗</div>
        <div className="terminal-text-bright mb-2">║      CREW ROSTER             ║</div>
        <div className="terminal-text-bright mb-3">╚══════════════════════════════╝</div>

        {npcs.map((npc, idx) => (
          <div key={npc.id} className="mb-3">
            <div className="terminal-text-bright">{idx + 1}. {npc.name}</div>
            <div className="terminal-text-dim ml-3">Role: {npc.role}</div>
            <div className="ml-3">
              Affinity: [{createAffinityBar(npc.affinity)}] ({npc.affinity > 0 ? '+' : ''}{npc.affinity})
            </div>
            <div className="terminal-text-dim ml-3">Status: {npc.status || 'Indifferent'}</div>
            {npc.lastInteraction && (
              <div className="terminal-text-dim ml-3 text-xs">"{npc.lastInteraction}"</div>
            )}
          </div>
        ))}
      </div>
    );
  };

  const renderItems = () => {
    if (!gameState?.equippedItems || !itemsData) return null;

    return (
      <div className="terminal-text font-mono">
        <div className="terminal-text-bright mb-2">╔══════════════════════════════╗</div>
        <div className="terminal-text-bright mb-2">║      INVENTORY               ║</div>
        <div className="terminal-text-bright mb-3">╚══════════════════════════════╝</div>

        <div className="terminal-text-bright mb-2">Equipped ({gameState.equippedItems.length}/3):</div>
        {gameState.equippedItems.length === 0 && (
          <div className="terminal-text-dim ml-3">No items equipped</div>
        )}
        {gameState.equippedItems.map((itemId: string, idx: number) => {
          const item = itemsData.find((i) => i.id === itemId);
          if (!item) return null;

          return (
            <div key={itemId} className="mb-2">
              <div className="terminal-text-bright">{idx + 1}. {item.icon} {item.name}</div>
              <div className="terminal-text-dim ml-3">{item.description}</div>
              {item.skillBonusSkill && (
                <div className="ml-3 text-sm">Bonus: +{item.skillBonusValue} {item.skillBonusSkill}</div>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  const renderActions = () => {
    if (!gameState?.currentActions?.length) return null;

    return (
      <div className="mt-4 terminal-text font-mono">
        <div className="terminal-text-bright mb-2">═══ AVAILABLE ACTIONS ═══</div>
        {gameState.currentActions.map((action: ActionChip, idx: number) => (
          <div key={idx} className="mb-1 terminal-command-item" onClick={() => executeCommand(`${idx + 1}`)}>
            {idx + 1}. {action.action}
            <div className="terminal-text-dim ml-3 text-xs">{action.summary}</div>
            <span className="terminal-text-dim ml-3 text-xs">[{action.risk}]</span>
          </div>
        ))}
        <div className="terminal-text-dim mt-2 text-sm">Type 1-{gameState.currentActions.length} to select an action</div>
      </div>
    );
  };

  // Helper functions
  const createBar = (value: number, max: number) => {
    const filled = Math.round((value / max) * 20);
    const color = value > 60 ? '█' : value > 30 ? '▓' : '░';
    return color.repeat(filled) + '░'.repeat(20 - filled);
  };

  const createAffinityBar = (affinity: number) => {
    const normalized = Math.max(-3, Math.min(3, affinity));
    const position = normalized + 3; // 0-6 scale
    const bar = '░'.repeat(6).split('');
    bar[position] = '█';
    return bar.join('');
  };

  if (!gameState) {
    return (
      <div className="terminal-mode terminal-screen h-screen flex items-center justify-center">
        <div className="terminal-spinner">Loading game state</div>
      </div>
    );
  }

  return (
    <div 
      className="terminal-mode terminal-screen terminal-static terminal-power-on h-screen w-full flex flex-col p-4 overflow-hidden"
      onClick={handleTerminalClick}
      data-testid="terminal-game-page"
    >
      {/* Header */}
      <div className="terminal-border p-2 mb-3">
        <div className="terminal-text-bright text-center">
          ═══ QUEST TO URANUS - TERMINAL MODE ═══
        </div>
        <div className="terminal-text-dim text-center text-sm">
          Captain: {gameState.username} | Turn {gameState.turnNumber || 0}
        </div>
      </div>

      {/* Main terminal output */}
      <div 
        ref={terminalRef}
        className="flex-1 overflow-y-auto mb-3 font-mono text-sm space-y-2"
        data-testid="terminal-output"
      >
        {/* Show current view */}
        {viewMode === 'main' && (
          <>
            {/* Narrative Feed */}
            {typewriterText && (
              <div className="terminal-border p-3 mb-3">
                <div className="terminal-text-bright mb-2">
                  ┌─ TURN {gameState.turnNumber} ─┐
                </div>
                <div className="terminal-text whitespace-pre-wrap">{typewriterText}</div>
              </div>
            )}

            {/* Actions - only show after typing completes */}
            {typingComplete && renderActions()}
          </>
        )}

        {viewMode === 'stats' && renderStats()}
        {viewMode === 'crew' && renderCrew()}
        {viewMode === 'items' && renderItems()}

        {/* Command History */}
        {commandHistory.map((line, idx) => (
          <div key={idx} className={line.startsWith('>') ? 'terminal-text-bright' : 'terminal-text'}>
            {line}
          </div>
        ))}
      </div>

      {/* Command Input */}
      <div className="flex items-center gap-2 terminal-border p-2">
        <span className="terminal-prompt">$</span>
        <input
          ref={inputRef}
          type="text"
          value={currentCommand}
          onChange={(e) => setCurrentCommand(e.target.value)}
          onKeyDown={handleKeyDown}
          className="terminal-input flex-1"
          placeholder="Type 'help' for commands..."
          autoComplete="off"
          autoFocus
          data-testid="terminal-input"
        />
        <span className="terminal-cursor"></span>
      </div>

      {/* Footer hints */}
      <div className="terminal-text-dim text-xs mt-2 text-center">
        Type "help" for commands | "stats" "crew" "items" to view details | 1-5 to select action | "exit" to quit
      </div>
    </div>
  );
}

