import { writeFile, readFile } from "fs/promises";
import { existsSync } from "fs";
import path from "path";
import { storage } from "./storage.js";
import type { ImagePrompt } from "@shared/schema";

const IMAGE_PROMPTS_FILE = path.join(process.cwd(), "server", "image_prompts.json");

interface CompiledImagePrompt extends ImagePrompt {
  compiledTemplate: string;
}

let imagePromptCache: CompiledImagePrompt[] = [];

export async function exportImagePromptsToJSON(): Promise<void> {
  console.log("Exporting image prompts from database to JSON...");

  const dbImagePrompts = await storage.getActiveImagePrompts();

  if (dbImagePrompts.length === 0) {
    console.warn("⚠️  No active image prompts found in database. Creating empty image prompts file.");
    await writeFile(IMAGE_PROMPTS_FILE, JSON.stringify([], null, 2), "utf-8");
    return;
  }

  // Get visual style base prompt
  const visualStylePrompt = await storage.getPromptTemplate('visual_style_prompt');
  const visualStyleContent = visualStylePrompt?.content || '';

  // Compile prompts with visual style inheritance
  const compiledPrompts: CompiledImagePrompt[] = dbImagePrompts.map(prompt => {
    let compiledTemplate = prompt.promptTemplate;

    if (prompt.inheritVisualStyle && visualStyleContent) {
      compiledTemplate = `VISUAL STYLE:\n${visualStyleContent}\n\nSUBJECT:\n${prompt.promptTemplate}`;
    }

    return {
      ...prompt,
      compiledTemplate
    };
  });

  await writeFile(IMAGE_PROMPTS_FILE, JSON.stringify(compiledPrompts, null, 2), "utf-8");
  console.log(`✅ Exported ${compiledPrompts.length} image prompts to ${IMAGE_PROMPTS_FILE}`);
}

export async function loadImagePromptsIntoMemory(): Promise<void> {
  console.log("Loading image prompts from JSON into memory...");

  if (!existsSync(IMAGE_PROMPTS_FILE)) {
    throw new Error(`Image prompts file not found at ${IMAGE_PROMPTS_FILE}. Run exportImagePromptsToJSON() first.`);
  }

  const fileContent = await readFile(IMAGE_PROMPTS_FILE, "utf-8");

  let promptsArray: CompiledImagePrompt[];
  try {
    promptsArray = JSON.parse(fileContent);
  } catch (error) {
    throw new Error(`Failed to parse image_prompts.json: ${error}`);
  }

  imagePromptCache = promptsArray;

  console.log(`✅ Loaded ${imagePromptCache.length} image prompts into memory cache`);
}

export async function syncImagePromptsFromDatabase(): Promise<void> {
  await exportImagePromptsToJSON();
  await loadImagePromptsIntoMemory();
  console.log("✅ Image prompts synchronized from database");
}

export function getActiveImagePrompts(): CompiledImagePrompt[] {
  return imagePromptCache;
}

export function getImagePromptById(id: string): CompiledImagePrompt | undefined {
  return imagePromptCache.find(prompt => prompt.id === id);
}

export function getImagePromptByName(name: string): CompiledImagePrompt | undefined {
  return imagePromptCache.find(prompt => prompt.name === name);
}

export function getImagePromptsBySceneType(sceneType: string): CompiledImagePrompt[] {
  return imagePromptCache.filter(prompt => 
    (prompt.sceneTypes as string[]).includes(sceneType)
  );
}

export function getImagePromptCacheStats(): { count: number; prompts: string[] } {
  return {
    count: imagePromptCache.length,
    prompts: imagePromptCache.map(p => p.name)
  };
}

