import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Sparkles, AlertCircle } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useQuery } from "@tanstack/react-query";

interface ImageTestModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  templateName: string;
  promptTemplate: string;
  inheritVisualStyle: boolean;
}

interface TestResult {
  imageUrl: string;
  promptUsed: string;
  debugInfo: {
    model: string;
    size: string;
    quality: string;
    background: string;
    moderation: string;
    generationTime: number;
    variables: Record<string, string>;
  };
}

export function ImageTestModal({ open, onOpenChange, templateName, promptTemplate, inheritVisualStyle }: ImageTestModalProps) {
  const [variables, setVariables] = useState<Record<string, string>>({});
  const [detectedVariables, setDetectedVariables] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<TestResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [visualStyleContent, setVisualStyleContent] = useState<string>("");

  // Fetch prompts to get visual style
  const { data: prompts } = useQuery<any[]>({
    queryKey: ["/api/prompts"],
  });

  useEffect(() => {
    if (prompts) {
      const visualStylePrompt = prompts.find((p: any) => p.name === 'visual_style_prompt');
      if (visualStylePrompt) {
        setVisualStyleContent(visualStylePrompt.content);
      }
    }
  }, [prompts]);

  useEffect(() => {
    if (open) {
      // Extract variables from template using regex
      const variablePattern = /\{\{([A-Z_]+)\}\}/g;
      const matches = Array.from(promptTemplate.matchAll(variablePattern));
      const uniqueVars = Array.from(new Set(matches.map(m => m[1])));

      setDetectedVariables(uniqueVars);

      // Initialize with default values
      const defaultValues: Record<string, string> = {};
      uniqueVars.forEach(varName => {
        switch(varName) {
          case 'CURRENT_NARRATIVE':
            defaultValues[varName] = 'The ship drifts through deep space, its hull groaning under mysterious pressure.';
            break;
          case 'SEGMENT':
            defaultValues[varName] = 'Belt';
            break;
          case 'DAY':
            defaultValues[varName] = '5';
            break;
          case 'HULL':
          case 'OXYGEN':
          case 'FUEL':
          case 'FOOD':
          case 'MORALE':
            defaultValues[varName] = '75';
            break;
          case 'EQUIPPED_ITEMS':
            defaultValues[varName] = 'Duct Tape Deluxe (🔧), Manual (📖)';
            break;
          case 'NPC_SUMMARY':
            defaultValues[varName] = 'Pilot Lyra (Navigator), Engineer Grom (Chief Engineer)';
            break;
          case 'ABSURDITY_DESCRIPTION':
            defaultValues[varName] = 'Frequent bureaucratic absurdity with clear innuendo';
            break;
          default:
            defaultValues[varName] = '';
        }
      });

      setVariables(defaultValues);
      setResult(null);
      setError(null);
    }
  }, [open, promptTemplate]);

  const handleGenerate = async () => {
    setIsGenerating(true);
    setError(null);
    setResult(null);

    try {
      const response = await apiRequest("POST", "/api/test-generate-image", {
        templateName,
        variables
      });
      const data = await response.json() as TestResult;

      setResult(data);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Failed to generate image";
      setError(errorMessage);
      console.error("Image generation error:", err);
    } finally {
      setIsGenerating(false);
    }
  };

  const getCompiledPrompt = () => {
    let compiled = promptTemplate;

    // Apply visual style if inherited (matches backend compilation)
    if (inheritVisualStyle && visualStyleContent) {
      compiled = `VISUAL STYLE:\n${visualStyleContent}\n\nSUBJECT:\n${promptTemplate}`;
    }

    // Replace variables
    Object.entries(variables).forEach(([key, value]) => {
      compiled = compiled.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), value);
    });
    return compiled;
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle>Test Image Generation: {templateName}</DialogTitle>
          <DialogDescription>
            Fill in the variable values and generate a test image to verify the template and API access
          </DialogDescription>
        </DialogHeader>

        <ScrollArea className="max-h-[70vh] pr-4">
          <div className="space-y-6">
            {/* Variable Inputs */}
            {detectedVariables.length > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle>Template Variables</CardTitle>
                  <CardDescription>
                    Provide values for each variable detected in the template
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  {detectedVariables.map(varName => (
                    <div key={varName}>
                      <Label htmlFor={`var-${varName}`} data-testid={`label-var-${varName.toLowerCase()}`}>
                        {varName}
                      </Label>
                      {varName === 'CURRENT_NARRATIVE' ? (
                        <Textarea
                          id={`var-${varName}`}
                          value={variables[varName] || ''}
                          onChange={(e) => setVariables({ ...variables, [varName]: e.target.value })}
                          placeholder={`Enter value for ${varName}...`}
                          className="min-h-[100px] font-mono text-sm"
                          data-testid={`input-var-${varName.toLowerCase()}`}
                        />
                      ) : (
                        <Input
                          id={`var-${varName}`}
                          value={variables[varName] || ''}
                          onChange={(e) => setVariables({ ...variables, [varName]: e.target.value })}
                          placeholder={`Enter value for ${varName}...`}
                          data-testid={`input-var-${varName.toLowerCase()}`}
                        />
                      )}
                    </div>
                  ))}
                </CardContent>
              </Card>
            )}

            {/* Compiled Prompt Preview */}
            <Card>
              <CardHeader>
                <CardTitle>Compiled Prompt Preview</CardTitle>
                <CardDescription>
                  This is what will be sent to the AI after variable substitution
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Textarea
                  value={getCompiledPrompt()}
                  readOnly
                  className="min-h-[120px] font-mono text-sm bg-muted"
                  data-testid="textarea-compiled-prompt"
                />
              </CardContent>
            </Card>

            {/* Generate Button */}
            <Button
              onClick={handleGenerate}
              disabled={isGenerating}
              className="w-full"
              data-testid="button-generate-test-image"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Generating Image...
                </>
              ) : (
                <>
                  <Sparkles className="h-4 w-4 mr-2" />
                  Generate Test Image
                </>
              )}
            </Button>

            {/* Error Display */}
            {error && (
              <Card className="border-destructive">
                <CardHeader>
                  <CardTitle className="text-destructive flex items-center gap-2">
                    <AlertCircle className="h-5 w-5" />
                    Generation Failed
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-sm" data-testid="text-error-message">{error}</p>
                </CardContent>
              </Card>
            )}

            {/* Result Display */}
            {result && (
              <>
                {/* Generated Image */}
                <Card>
                  <CardHeader>
                    <CardTitle>Generated Image</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex justify-center bg-muted rounded-lg p-4">
                      <img 
                        src={result.imageUrl} 
                        alt="Generated test image" 
                        className="max-w-full h-auto rounded"
                        data-testid="img-generated"
                      />
                    </div>
                  </CardContent>
                </Card>

                {/* Debug Information */}
                <Card>
                  <CardHeader>
                    <CardTitle>Debug Information</CardTitle>
                    <CardDescription>
                      Technical details about the generation request
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <Label className="text-muted-foreground">Model</Label>
                        <p className="font-mono" data-testid="text-debug-model">{result.debugInfo.model}</p>
                      </div>
                      <div>
                        <Label className="text-muted-foreground">Size</Label>
                        <p className="font-mono" data-testid="text-debug-size">{result.debugInfo.size}</p>
                      </div>
                      <div>
                        <Label className="text-muted-foreground">Quality</Label>
                        <p className="font-mono" data-testid="text-debug-quality">{result.debugInfo.quality}</p>
                      </div>
                      <div>
                        <Label className="text-muted-foreground">Background</Label>
                        <p className="font-mono" data-testid="text-debug-background">{result.debugInfo.background}</p>
                      </div>
                      <div>
                        <Label className="text-muted-foreground">Moderation</Label>
                        <p className="font-mono" data-testid="text-debug-moderation">{result.debugInfo.moderation}</p>
                      </div>
                      <div>
                        <Label className="text-muted-foreground">Generation Time</Label>
                        <p className="font-mono" data-testid="text-debug-time">{(result.debugInfo.generationTime / 1000).toFixed(2)}s</p>
                      </div>
                    </div>

                    <div>
                      <Label className="text-muted-foreground">Final Prompt Sent</Label>
                      <Textarea
                        value={result.promptUsed}
                        readOnly
                        className="min-h-[100px] font-mono text-sm bg-muted mt-2"
                        data-testid="textarea-final-prompt"
                      />
                    </div>
                  </CardContent>
                </Card>
              </>
            )}
          </div>
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

server/imageStorage.ts.content:
import { promises as fs } from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';

export interface ImageMetadata {
  templateName: string;
  promptHash: string;
  variablesHash: string;
  gameId?: string;
  turnNumber?: number;
  generatedAt: Date;
}

export interface StorageStats {
  totalFiles: number;
  totalSizeBytes: number;
  averageFileSize: number;
  oldestFile: Date | null;
  newestFile: Date | null;
}

const STORAGE_DIR = path.join(process.cwd(), 'generated_images');

// Ensure storage directory exists
async function ensureStorageDir(): Promise<void> {
  try {
    await fs.access(STORAGE_DIR);
  } catch {
    await fs.mkdir(STORAGE_DIR, { recursive: true });
  }
}

export async function saveImageToFile(
  base64Data: string, 
  metadata: ImageMetadata
): Promise<{ filePath: string; fileSize: number }> {
  await ensureStorageDir();

  // Extract base64 data (remove data:image/png;base64, prefix if present)
  const base64Content = base64Data.includes(',') 
    ? base64Data.split(',')[1] 
    : base64Data;

  // Create filename with template name and hash for uniqueness
  const filename = `${metadata.templateName}_${metadata.promptHash.substring(0, 8)}_${randomUUID().substring(0, 8)}.png`;
  const filePath = path.join(STORAGE_DIR, filename);

  // Convert base64 to buffer and write to file
  const buffer = Buffer.from(base64Content, 'base64');
  await fs.writeFile(filePath, buffer);

  // Get file stats for size
  const stats = await fs.stat(filePath);

  return {
    filePath,
    fileSize: stats.size
  };
}

export async function loadImageFromFile(filePath: string): Promise<string> {
  try {
    const buffer = await fs.readFile(filePath);
    const base64 = buffer.toString('base64');
    return `data:image/png;base64,${base64}`;
  } catch (error) {
    throw new Error(`Failed to load image from file: ${filePath}. Error: ${error}`);
  }
}

export async function deleteImageFile(filePath: string): Promise<void> {
  try {
    await fs.unlink(filePath);
  } catch (error) {
    // Don't throw if file doesn't exist
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
      throw new Error(`Failed to delete image file: ${filePath}. Error: ${error}`);
    }
  }
}

export async function getStorageStats(): Promise<StorageStats> {
  await ensureStorageDir();

  try {
    const files = await fs.readdir(STORAGE_DIR);
    const imageFiles = files.filter(file => file.endsWith('.png'));

    if (imageFiles.length === 0) {
      return {
        totalFiles: 0,
        totalSizeBytes: 0,
        averageFileSize: 0,
        oldestFile: null,
        newestFile: null
      };
    }

    let totalSize = 0;
    let oldestTime = Infinity;
    let newestTime = 0;

    for (const file of imageFiles) {
      const filePath = path.join(STORAGE_DIR, file);
      const stats = await fs.stat(filePath);

      totalSize += stats.size;

      const mtime = stats.mtime.getTime();
      if (mtime < oldestTime) oldestTime = mtime;
      if (mtime > newestTime) newestTime = mtime;
    }

    return {
      totalFiles: imageFiles.length,
      totalSizeBytes: totalSize,
      averageFileSize: totalSize / imageFiles.length,
      oldestFile: oldestTime === Infinity ? null : new Date(oldestTime),
      newestFile: newestTime === 0 ? null : new Date(newestTime)
    };
  } catch (error) {
    throw new Error(`Failed to get storage stats: ${error}`);
  }
}

export async function cleanupOrphanedFiles(validFilePaths: string[]): Promise<number> {
  await ensureStorageDir();

  try {
    const files = await fs.readdir(STORAGE_DIR);
    const imageFiles = files.filter(file => file.endsWith('.png'));

    let deletedCount = 0;

    for (const file of imageFiles) {
      const filePath = path.join(STORAGE_DIR, file);
      const isReferenced = validFilePaths.some(validPath => 
        path.resolve(validPath) === path.resolve(filePath)
      );

      if (!isReferenced) {
        await fs.unlink(filePath);
        deletedCount++;
      }
    }

    return deletedCount;
  } catch (error) {
    throw new Error(`Failed to cleanup orphaned files: ${error}`);
  }
}

