import { useState, useEffect } from 'react';
import { useLocation, Link } from 'wouter';
import { useQuery, useMutation } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { Play, Trash2, Loader2, HelpCircle } from 'lucide-react';
import CRTBackground from '@/components/CRTBackground';
import ImageSplashScreen from '@/components/ImageSplashScreen';
import { useToast } from '@/hooks/use-toast';
import type { GameState } from '@shared/schema';

export default function MainMenuPage() {
  const [, setLocation] = useLocation();
  const [username, setUsername] = useState<string | null>(null);
  const [absurdity] = useState(3);
  const [showImageSplash, setShowImageSplash] = useState(false);
  const [pendingGameData, setPendingGameData] = useState<GameState | null>(null);
  const { toast } = useToast();

  useEffect(() => {
    const storedUsername = localStorage.getItem('quest-to-uranus-username');
    if (!storedUsername) {
      setLocation('/');
      return;
    }
    setUsername(storedUsername);
  }, [setLocation]);

  const { data: userGames, refetch: refetchGames } = useQuery<GameState[]>({
    queryKey: [`/api/games/user/${username}`],
    enabled: !!username,
    refetchInterval: false
  });

  const startGameMutation = useMutation({
    mutationFn: async () => {
      if (!username) throw new Error('No username set');
      const response = await apiRequest('POST', '/api/game/start', {
        absurdity,
        username,
        displayMode: 'modern'
      });
      return await response.json();
    },
    onSuccess: (data: GameState) => {
      setPendingGameData(data);
      queryClient.setQueryData([`/api/game/${data.id}`], data);
      setShowImageSplash(true);
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to start game",
        variant: "destructive"
      });
    }
  });

  const deleteGameMutation = useMutation({
    mutationFn: async (gameIdToDelete: string) => {
      await apiRequest('DELETE', `/api/game/${gameIdToDelete}`);
    },
    onSuccess: () => {
      refetchGames();
      toast({
        title: "Game Deleted",
        description: "Voyage has been scrubbed"
      });
    }
  });

  const handleChangeCaptain = () => {
    localStorage.removeItem('quest-to-uranus-username');
    setLocation('/');
  };

  const handleStartNewVoyage = () => {
    startGameMutation.mutate();
  };

  const handleResumeGame = (gameId: string) => {
    setLocation(`/game/${gameId}`);
  };

  const handleImageSplashComplete = () => {
    if (pendingGameData) {
      setLocation(`/interview/${pendingGameData.id}`);
    }
  };

  if (showImageSplash) {
    return <ImageSplashScreen onComplete={handleImageSplashComplete} />;
  }

  if (!username) {
    return null;
  }

  return (
    <div className="relative w-full min-h-screen overflow-auto bg-black font-mono text-[#00ffff]">
      <CRTBackground intensity="low" />

      <div className="relative z-10 container mx-auto px-4 py-8 max-w-4xl">
        <div className="absolute top-4 right-4 sm:top-8 sm:right-8">
          <Link href="/help">
            <button
              className="p-2 sm:p-3 border-2 border-[#ffaa00] text-[#ffaa00] bg-[#001a0a] hover:bg-[#002a1a] hover:shadow-[0_0_20px_#ffaa00] transition-all"
              data-testid="button-help"
              title="How to Probe Uranus"
            >
              <HelpCircle className="w-5 h-5 sm:w-6 sm:h-6" />
            </button>
          </Link>
        </div>

        <div className="text-center mb-8">
          <h1 className="md:text-5xl font-bold drop-shadow-[0_0_15px_#00ffff] mb-2 animate-[flicker_3s_infinite] text-[46px]">
            <span className="block">█▓ THERES MONEY IN URANUS ▓█</span>
            <span className="block">█▓ Ready to Occupy? {username} ▓█</span>
          </h1>
          <div className="text-[#ffaa00] text-sm">
            [ MISSION CONTROL INTERFACE ]
          </div>
        </div>

        <div className="space-y-6">
          <div className="border-2 border-[#00ffff] bg-[#001a1a] p-6 shadow-[0_0_20px_#00ffff]">
            <div className="space-y-6">
              <div>
                <div className="flex items-center justify-between mb-3">
                  <div className="text-[#ff0000] text-sm flex items-center gap-2">
                    <span>[ ABSURDITY DIAL ]</span>
                    <span className="animate-[flashWarning_1s_infinite] text-[#ffaa00] text-xs font-bold">
                      ⚠ UNDER REPAIR ⚠
                    </span>
                  </div>
                  <div className="text-[#ff0000] text-xl font-bold animate-[flashWarning_1s_infinite]">{absurdity}</div>
                </div>
                <div className="flex gap-2 mb-2">
                  {[0, 1, 2, 3].map((level) => (
                    <button
                      key={level}
                      disabled
                      className={`flex-1 px-3 py-2 border font-bold transition-all cursor-not-allowed ${
                        absurdity === level
                          ? 'border-[#ff0000] text-[#ff0000] bg-[#1a0000] shadow-[0_0_15px_#ff0000]'
                          : 'border-[#333333] text-[#666666] bg-transparent opacity-50'
                      }`}
                      data-testid={`button-absurdity-${level}`}
                    >
                      {level}
                    </button>
                  ))}
                </div>
                <div className="text-[#ff6600] text-xs space-y-1 animate-[flashWarning_1s_infinite]">
                  <div>⚠ MALFUNCTION: DIAL STUCK ON MAXIMUM CHAOS ⚠</div>
                  <div className="text-[#00aaaa] animate-none">System will resume normal operation once repairs are complete</div>
                </div>
              </div>

              <button
                onClick={handleStartNewVoyage}
                disabled={startGameMutation.isPending}
                className="w-full px-8 py-4 border-2 border-[#00ffff] text-[#00ffff] bg-[#001a1a] hover:bg-[#002f2f] hover:shadow-[0_0_30px_#00ffff] disabled:opacity-30 disabled:cursor-not-allowed transition-all duration-300 font-bold text-lg tracking-wide animate-[pulseGlow_4s_infinite]"
                data-testid="button-new-game"
              >
                {startGameMutation.isPending ? (
                  <span className="flex items-center justify-center gap-2">
                    <Loader2 className="w-5 h-5 animate-spin" />
                    INITIALIZING...
                  </span>
                ) : (
                  <span>▶ START NEW VOYAGE</span>
                )}
              </button>
            </div>
          </div>

          {userGames && userGames.length > 0 && (
            <div className="border-2 border-[#ffaa00] bg-[#1a1000] p-6 shadow-[0_0_20px_#ffaa00]">
              <div className="text-[#ffaa00] text-sm mb-4">[ SAVED VOYAGES ]</div>
              <div className="space-y-3">
                {userGames.map((game) => (
                  <div
                    key={game.id}
                    className="border border-[#ffaa00] bg-[#0a0a00] p-4 hover:bg-[#1a1000] transition-colors"
                  >
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-sm text-[#ffaa00] font-bold">
                            Day {game.day} - {game.segment}
                          </span>
                          {game.isComplete && (
                            <span className="text-xs px-2 py-0.5 border border-[#ff66ff] text-[#ff66ff]">
                              {game.failureReason ? 'FAILED' : 'COMPLETE'}
                            </span>
                          )}
                        </div>
                        <div className="text-xs text-[#00aaaa]">
                          Turn {game.turnNumber} • Absurdity {game.absurdity}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button
                          onClick={() => handleResumeGame(game.id)}
                          className="px-4 py-2 border-2 border-[#00ffff] text-[#00ffff] bg-[#001a1a] hover:bg-[#002f2f] hover:shadow-[0_0_15px_#00ffff] transition-all font-bold flex items-center gap-1"
                          data-testid={`button-resume-${game.id}`}
                        >
                          <Play className="w-3 h-3" />
                          {game.isComplete ? 'VIEW' : 'RESUME'}
                        </button>
                        <button
                          onClick={() => deleteGameMutation.mutate(game.id)}
                          disabled={deleteGameMutation.isPending}
                          className="px-3 py-2 border border-[#ff0000] text-[#ff0000] bg-transparent hover:bg-[#1a0000] disabled:opacity-30 transition-all"
                          data-testid={`button-delete-${game.id}`}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {userGames && userGames.length === 0 && (
            <div className="border-2 border-[#00aaaa] bg-[#001a1a] p-6 text-center">
              <p className="text-[#00aaaa] text-sm">░▒▓ No saved voyages yet ▓▒░</p>
            </div>
          )}

          <div className="text-center">
            <button
              onClick={handleChangeCaptain}
              className="px-6 py-2 border border-[#00aaaa] text-[#00aaaa] bg-transparent hover:bg-[#001a1a] hover:border-[#00ffff] hover:text-[#00ffff] transition-all text-sm"
              data-testid="button-change-captain"
            >
              [ CHANGE CAPTAIN ]
            </button>
          </div>
        </div>

        <div className="mt-8 text-center text-[#00aaaa] text-xs opacity-70">
          ░▒▓ ETH LOVES URANUS • MISSION CONTROL 2025-2069 ▓▒░
        </div>
      </div>

      <style>{`
        @keyframes pulseGlow {
          0%, 100% { box-shadow: 0 0 10px #00ffff; }
          50% { box-shadow: 0 0 35px #00ffff; }
        }
        @keyframes flicker {
          0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% { opacity: 1; }
          20%, 24%, 55% { opacity: 0.85; }
        }
        @keyframes flashWarning {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.4; }
        }
      `}</style>
    </div>
  );
}

client/src/pages/LoadingPage.tsx.content:
import { useEffect, useState } from 'react';
import { useLocation } from 'wouter';
import videoSplash1 from '@assets/Uranus-HawkingFinal_1761531071513.mp4';
import videoSplash2 from '@assets/Uranus-AskNotWhatUranus_1761533619310.mp4';

export default function LoadingPage() {
  const [, setLocation] = useLocation();
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const videos = [videoSplash1, videoSplash2];
    let loadedCount = 0;

    const preloadVideo = (src: string): Promise<void> => {
      return new Promise((resolve) => {
        const video = document.createElement('video');
        video.preload = 'auto';

        const updateProgress = () => {
          loadedCount++;
          setProgress(Math.round((loadedCount / videos.length) * 100));
        };

        video.oncanplaythrough = () => {
          updateProgress();
          resolve();
        };

        video.onerror = () => {
          updateProgress();
          resolve(); // Still resolve to prevent blocking
        };

        video.src = src;
        video.load();
      });
    };

    Promise.all(videos.map(preloadVideo)).then(() => {
      setTimeout(() => {
        const storedUsername = localStorage.getItem('quest-to-uranus-username');
        if (storedUsername) {
          setLocation('/menu');
        } else {
          setLocation('/welcome');
        }
      }, 300);
    });
  }, [setLocation]);

  return (
    <div className="fixed inset-0 bg-black flex flex-col items-center justify-center font-mono">
      <div className="flex flex-col items-center gap-6">
        <div className="flex gap-2">
          <div className="w-3 h-3 bg-[#00ffff] rounded-full animate-pulse" style={{ animationDelay: '0ms' }} />
          <div className="w-3 h-3 bg-[#00ffff] rounded-full animate-pulse" style={{ animationDelay: '200ms' }} />
          <div className="w-3 h-3 bg-[#00ffff] rounded-full animate-pulse" style={{ animationDelay: '400ms' }} />
        </div>

        <div className="text-[#00ffff] text-sm tracking-wider">
          LOADING E.L.O.N. - Edgelord Liguistical Original Narratative UNIT
        </div>

        <div className="w-64 h-1 bg-[#001a1a] border border-[#00aaaa] overflow-hidden">
          <div 
            className="h-full bg-[#00ffff] transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>

        <div className="text-[#00aaaa] text-xs">
          {progress}%
        </div>
      </div>
    </div>
  );
}

